#[derive(Debug)]
struct LocalFileScan {
    files: Vec<serde_json::Value>,
    /// Exact stat fingerprints captured for every returned path, plus a
    /// one-bit racy-clean admission result. Keeping that bit beside the sole
    /// fingerprint avoids duplicating a million-path map on large warm scans.
    fingerprints: std::collections::HashMap<String, ScannedLocalFileFingerprint>,
    content_files_read: usize,
    content_bytes_read: u64,
    reused_files: usize,
    /// Paths observed during the walk that indexing policy explicitly forbids.
    /// They are safe tombstones even for a capped scan because no absence
    /// inference is involved and they help remove content indexed by older
    /// clients before the policy existed.
    policy_deleted_paths: Vec<String>,
    /// True only when every indexable candidate was enumerated and read.
    /// Absence-based deletions and full manifest replacement are unsafe when
    /// a file cap, walk error, metadata error, or read error made the scan
    /// partial.
    complete: bool,
    /// Every indexable path observed across the completed bounded scan epoch.
    /// Present only when `complete` is true. A finite scan accumulates this in
    /// an append-only epoch journal so the last page can safely infer absence
    /// without loading or rewriting a million-path manifest on every page.
    observed_paths: Option<std::collections::HashSet<String>>,
    cursor_update: ScanCursorUpdate,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
enum ScanCursorUpdate {
    Keep,
    Set {
        path: std::path::PathBuf,
        seen_path: std::path::PathBuf,
        value: String,
        page_paths: Vec<String>,
        valid: bool,
        reset_seen: bool,
    },
    Clear {
        path: std::path::PathBuf,
        seen_path: std::path::PathBuf,
    },
}

#[derive(Debug, Clone)]
struct ScanEpochState {
    cursor: String,
    valid: bool,
    applied_receipt_id: Option<Uuid>,
}

/// Stable local scope for a checkout hash manifest.
///
/// A backend project may be indexed from multiple workspaces, machines, and
/// worktrees. Project UUID alone is therefore not enough to identify which
/// local filesystem snapshot a manifest describes. The scope digest binds the
/// cache to the canonical checkout plus the validated workspace/repository
/// identity captured before the scan.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
struct HashManifestScope {
    project_id: Uuid,
    workspace_id: Uuid,
    checkout_root: String,
    checkout_identity: String,
    scope_id: String,
}

/// Credential-free provenance for one validated checkout or folder snapshot.
///
/// This accompanies every local-root ingest both as a batch object and as
/// compatible flat per-file fields. It intentionally contains no hostname or
/// absolute local path; those remain installation-local routing details.
#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
struct CheckoutProvenance {
    checkout_id: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    installation_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    machine_id: Option<String>,
    repository_fingerprint: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    repository_identity: Option<String>,
    git_ref_kind: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    git_branch: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    git_commit_sha: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    git_commit_timestamp: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    is_default_branch: Option<bool>,
    #[serde(skip_serializing_if = "Option::is_none")]
    dirty: Option<bool>,
    captured_at: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LocalCheckoutSnapshot {
    guard: String,
    provenance: CheckoutProvenance,
}

/// Metadata identity used only as a content-read avoidance proof. Unix ctime,
/// inode, device, mode, size, and nanosecond mtime are all included so an
/// inode replacement or a preserved-mtime rewrite cannot masquerade as the
/// previously hashed file. Other platforms fail closed and keep hashing.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
struct LocalFileFingerprint {
    size: u64,
    modified_seconds: i64,
    modified_nanoseconds: i64,
    changed_seconds: i64,
    changed_nanoseconds: i64,
    device: u64,
    inode: u64,
    mode: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ScannedLocalFileFingerprint {
    fingerprint: LocalFileFingerprint,
    reusable: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct FilesystemTimestamp {
    seconds: i64,
    nanoseconds: i64,
}

impl FilesystemTimestamp {
    fn closed_tick_cutoff_now() -> Option<Self> {
        const RACY_CLEAN_FENCE: Duration = Duration::from_secs(2);

        let cutoff = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .ok()?
            .checked_sub(RACY_CLEAN_FENCE)?;
        Some(Self {
            seconds: i64::try_from(cutoff.as_secs()).ok()?,
            nanoseconds: i64::from(cutoff.subsec_nanos()),
        })
    }
}

#[derive(Debug, Clone, Copy)]
struct FingerprintReusePolicy {
    closed_tick_cutoff: Option<FilesystemTimestamp>,
    refresh_cutoff_per_file: bool,
    /// Production always probes the filesystem. Tests can override the probe
    /// to cover admission and fail-closed behavior without depending on the
    /// host runner's mount type.
    filesystem_supported_override: Option<bool>,
}

impl FingerprintReusePolicy {
    fn production() -> Self {
        Self {
            closed_tick_cutoff: None,
            refresh_cutoff_per_file: true,
            filesystem_supported_override: None,
        }
    }

    fn cutoff_for_next_file(self) -> Option<FilesystemTimestamp> {
        if self.refresh_cutoff_per_file {
            FilesystemTimestamp::closed_tick_cutoff_now()
        } else {
            self.closed_tick_cutoff
        }
    }
}

impl LocalFileFingerprint {
    fn timestamps_are_closed(&self, cutoff: Option<FilesystemTimestamp>) -> bool {
        let Some(cutoff) = cutoff else {
            return false;
        };
        if self.modified_seconds < 0
            || self.changed_seconds < 0
            || !(0..1_000_000_000).contains(&self.modified_nanoseconds)
            || !(0..1_000_000_000).contains(&self.changed_nanoseconds)
        {
            return false;
        }
        (self.modified_seconds, self.modified_nanoseconds) <= (cutoff.seconds, cutoff.nanoseconds)
            && (self.changed_seconds, self.changed_nanoseconds)
                <= (cutoff.seconds, cutoff.nanoseconds)
    }
}

