const FINGERPRINT_SEMANTICS_RACY_CLEAN_V1: &str = "unix-stat-racy-clean-v1";

/// Durable acknowledgement for one filesystem scan page whose API writes were
/// accepted asynchronously. The page's local manifest/cursor state is not
/// advanced until every job is terminal and the primary index attests the
/// exact project/workspace. Keeping this on disk prevents process restarts
/// from uploading the same capped page forever.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
struct PendingScanPageReceipt {
    version: u32,
    #[serde(default)]
    fingerprint_semantics: Option<String>,
    receipt_id: Uuid,
    project_id: Uuid,
    workspace_id: Uuid,
    checkout_root: String,
    checkout_guard: Option<String>,
    manifest_scope: HashManifestScope,
    manifest_patch: Vec<HashManifestPatchEntry>,
    cursor_update: ScanCursorUpdate,
    job_ids: Vec<Uuid>,
    scan_complete: bool,
    sensitive_cleanup_pending: bool,
    created_at: String,
}

#[derive(Debug)]
enum PendingScanReceiptReconcile {
    None,
    Pending { job_ids: Vec<Uuid> },
    Applied { scan_complete: bool },
    Reset,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PendingScanJobState {
    Pending,
    Completed,
    Failed,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum BoundedTextReadError {
    Transient,
    InvalidUtf8 { bytes_read: usize },
}

