#[derive(Debug)]
pub enum TargetedFileDecision {
    Upload(serde_json::Value),
    /// The contained path is intentionally excluded by indexing policy, so a
    /// previously indexed copy may be removed without reading local bytes.
    Delete(String),
    /// Containment, ignore evaluation, metadata, or reading was inconclusive.
    /// Automatic writers must leave any existing index entry untouched.
    Reject,
}

/// Process-wide project ingest lease. Every local ingest entry point funnels
/// through `ingest_local_with_progress`, so this prevents the active refresh,
/// search repair, hook drain, keep-warm daemon, setup, and explicit project
/// tools from scanning and mutating the same project concurrently.
///
/// A project UUID is globally unique and is the correct key even when a
/// re-root operation changes the checkout path while work is in flight.
static PROJECT_INGESTS_IN_FLIGHT: OnceLock<Mutex<std::collections::HashSet<Uuid>>> =
    OnceLock::new();

#[derive(Debug)]
struct ProjectIngestLease {
    project_id: Uuid,
}

impl ProjectIngestLease {
    fn acquire(project_id: Uuid) -> Result<Self> {
        let in_flight =
            PROJECT_INGESTS_IN_FLIGHT.get_or_init(|| Mutex::new(std::collections::HashSet::new()));
        let mut guard = in_flight
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if !guard.insert(project_id) {
            return Err(Error::Validation(format!(
                "ingest already in progress for project {}; concurrent refresh was coalesced",
                project_id
            )));
        }
        Ok(Self { project_id })
    }
}

impl Drop for ProjectIngestLease {
    fn drop(&mut self) {
        let Some(in_flight) = PROJECT_INGESTS_IN_FLIGHT.get() else {
            return;
        };
        let mut guard = in_flight
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        guard.remove(&self.project_id);
    }
}

// ---------------------------------------------------------------------------
// Per-request auth override via tokio task-local
// ---------------------------------------------------------------------------

tokio::task_local! {
    /// Per-request auth override set by the HTTP transport layer.
    /// Tools executed within the scope automatically inherit this auth context.
    static TASK_AUTH_OVERRIDE: AuthOverride;
}

tokio::task_local! {
    /// Per-request config override set by the HTTP transport layer.
    /// Tools executed within the scope automatically inherit these preferences.
    static TASK_CONFIG_OVERRIDE: ConfigOverride;
}

tokio::task_local! {
    /// Per-request session identity set by the HTTP transport layer from the
    /// authenticated subject (JWT `sub`, or SHA-256 of the API key). Used by
    /// `SessionManager` to partition in-memory `SessionState` across callers
    /// so one tenant's folder_path / workspace_id / project_id never bleeds
    /// into another tenant's response. Unset for CLI / local mode where the
    /// process is single-tenant by construction.
    static TASK_SESSION_KEY: SessionKey;
}

tokio::task_local! {
    /// Stable authenticated caller identity used only for caller-sensitive
    /// caches. Unlike `TASK_SESSION_KEY`, this deliberately excludes the MCP
    /// session id so reconnecting clients can reuse safe warm entries without
    /// sharing mutable `SessionManager` state between concurrent sessions.
    ///
    /// The HTTP transport installs an opaque, versioned SHA-256 token. Raw JWT
    /// subjects and API keys must never enter this task local.
    static TASK_CALLER_CACHE_IDENTITY: String;
}

tokio::task_local! {
    /// Per-request model id (registry-canonical) for the agent driving this
    /// turn. Set by the tool registry from the file-backed session model cache
    /// the hook layer warms. `request()` / `request_text()` forward it as the
    /// `X-ContextStream-Model` header so server-side compliance events attribute
    /// to the real model instead of the `unknown` bucket.
    static TASK_MODEL_ID: String;
}

/// Run a future scoped to the agent's model id (registry-canonical). Any
/// `ContextStreamClient` request inside `f` forwards it as `X-ContextStream-Model`.
pub async fn run_with_model_id<F, Fut>(model_id: String, f: F) -> Fut::Output
where
    F: FnOnce() -> Fut,
    Fut: std::future::Future,
{
    TASK_MODEL_ID.scope(model_id, f()).await
}

/// Read the current task-local model id, if any.
pub fn get_task_model_id() -> Option<String> {
    TASK_MODEL_ID.try_with(|m| m.clone()).ok()
}

tokio::task_local! {
    /// Per-request MCP session id (`Mcp-Session-Id` header) set by the HTTP
    /// transport layer. Lets tools attach a durable session identity to
    /// backend calls (init scope persistence, search scope rehydration) so
    /// scope survives gateway pod restarts and multi-replica routing where
    /// in-memory SessionState does not (audit 2026-07-17).
    static TASK_MCP_SESSION_ID: String;
}

tokio::task_local! {
    /// Per-request managed installation identity supplied by the hosted MCP
    /// transport. Bridge refresh routing must use the caller's installation,
    /// not whatever filesystem happens to exist on a gateway pod.
    static TASK_INSTALLATION_ID: Uuid;
}

/// Run a future scoped to the transport-level MCP session id.
pub async fn run_with_mcp_session_id<F, Fut>(session_id: String, f: F) -> Fut::Output
where
    F: FnOnce() -> Fut,
    Fut: std::future::Future,
{
    TASK_MCP_SESSION_ID.scope(session_id, f()).await
}

/// Read the current task-local MCP session id, if any. `None` outside an
/// HTTP request (CLI/stdio, background tasks, tests).
pub fn get_task_mcp_session_id() -> Option<String> {
    TASK_MCP_SESSION_ID.try_with(|s| s.clone()).ok()
}

/// Run a future scoped to the managed installation that issued the hosted MCP
/// request.
pub async fn run_with_installation_id<F, Fut>(installation_id: Uuid, f: F) -> Fut::Output
where
    F: FnOnce() -> Fut,
    Fut: std::future::Future,
{
    TASK_INSTALLATION_ID.scope(installation_id, f()).await
}

/// Read the current hosted request's managed installation identity.
pub fn get_task_installation_id() -> Option<Uuid> {
    TASK_INSTALLATION_ID.try_with(|id| *id).ok()
}

fn effective_installation_id() -> Option<Uuid> {
    get_task_installation_id()
        .or_else(|| {
            std::env::var("CONTEXTSTREAM_INSTALLATION_ID")
                .ok()
                .and_then(|value| Uuid::parse_str(value.trim()).ok())
                .filter(|value| !value.is_nil())
        })
        .or_else(|| crate::activation::existing_installation_id().ok().flatten())
}

/// Run a future with a per-request auth override.
///
/// Any `ContextStreamClient::request()` call inside `f` will use this auth
/// context (API key, workspace ID, project ID) instead of the process-level
/// config, unless an explicit `RequestOptions.auth_override` is provided.
pub async fn run_with_auth_override<F, Fut>(auth: AuthOverride, f: F) -> Fut::Output
where
    F: FnOnce() -> Fut,
    Fut: std::future::Future,
{
    TASK_AUTH_OVERRIDE.scope(auth, f()).await
}

/// Read the current task-local auth override, if any.
pub fn get_task_auth_override() -> Option<AuthOverride> {
    TASK_AUTH_OVERRIDE.try_with(|a| a.clone()).ok()
}

/// Run a future with a per-request config override.
pub async fn run_with_config_override<F, Fut>(config: ConfigOverride, f: F) -> Fut::Output
where
    F: FnOnce() -> Fut,
    Fut: std::future::Future,
{
    TASK_CONFIG_OVERRIDE.scope(config, f()).await
}

/// Read the current task-local config override, if any.
pub fn get_task_config_override() -> Option<ConfigOverride> {
    TASK_CONFIG_OVERRIDE.try_with(|config| config.clone()).ok()
}

/// Capture all caller-sensitive task-local state before detaching work.
///
/// Tokio task locals do not propagate through `tokio::spawn`. Telemetry and
/// best-effort readiness delivery must therefore restore this snapshot or a
/// shared HTTP gateway silently sends detached requests without the caller's
/// auth, scope, session, or model attribution.
#[derive(Debug, Clone, Default)]
pub struct TaskContextSnapshot {
    session_key: Option<SessionKey>,
    caller_cache_identity: Option<String>,
    auth_override: Option<AuthOverride>,
    config_override: Option<ConfigOverride>,
    mcp_session_id: Option<String>,
    model_id: Option<String>,
    installation_id: Option<Uuid>,
}

pub fn capture_task_context() -> TaskContextSnapshot {
    TaskContextSnapshot {
        session_key: get_task_session_key(),
        caller_cache_identity: get_task_caller_cache_identity(),
        auth_override: get_task_auth_override(),
        config_override: get_task_config_override(),
        mcp_session_id: get_task_mcp_session_id(),
        model_id: get_task_model_id(),
        installation_id: get_task_installation_id(),
    }
}

/// Spawn best-effort work while preserving the current request's complete
/// task-local identity. This helper is intentionally the only supported path
/// for detached `ContextStreamClient` calls from shared transports.
pub fn spawn_with_task_context<Fut, T>(future: Fut) -> tokio::task::JoinHandle<T>
where
    Fut: std::future::Future<Output = T> + Send + 'static,
    T: Send + 'static,
{
    let context = capture_task_context();
    tokio::spawn(async move {
        let mut scoped: std::pin::Pin<Box<dyn std::future::Future<Output = T> + Send + 'static>> =
            Box::pin(future);

        if let Some(model_id) = context.model_id {
            let inner = scoped;
            scoped = Box::pin(async move { run_with_model_id(model_id, || inner).await });
        }
        if let Some(installation_id) = context.installation_id {
            let inner = scoped;
            scoped =
                Box::pin(async move { run_with_installation_id(installation_id, || inner).await });
        }
        if let Some(mcp_session_id) = context.mcp_session_id {
            let inner = scoped;
            scoped =
                Box::pin(async move { run_with_mcp_session_id(mcp_session_id, || inner).await });
        }
        if let Some(config_override) = context.config_override {
            let inner = scoped;
            scoped =
                Box::pin(async move { run_with_config_override(config_override, || inner).await });
        }
        if let Some(auth_override) = context.auth_override {
            let inner = scoped;
            scoped = Box::pin(async move { run_with_auth_override(auth_override, || inner).await });
        }
        if let Some(session_key) = context.session_key {
            let inner = scoped;
            scoped = Box::pin(async move { run_with_session_key(session_key, || inner).await });
        }
        if let Some(caller_cache_identity) = context.caller_cache_identity {
            let inner = scoped;
            scoped = Box::pin(async move {
                run_with_caller_cache_identity(caller_cache_identity, || inner).await
            });
        }

        scoped.await
    })
}

#[cfg(test)]
mod task_context_tests {
    use super::*;

    #[tokio::test]
    async fn detached_task_restores_complete_caller_context() {
        let session_key = SessionKey::ApiKey("caller-partition".to_string());
        let auth = AuthOverride {
            api_key: Some("api-key".to_string()),
            workspace_id: Some(Uuid::new_v4()),
            project_id: Some(Uuid::new_v4()),
            ..Default::default()
        };
        let config = ConfigOverride {
            search_limit: Some(17),
            ..Default::default()
        };

        let observed = run_with_session_key(session_key.clone(), || async {
            run_with_caller_cache_identity("stable-caller-scope".to_string(), || async {
                run_with_auth_override(auth.clone(), || async {
                    run_with_config_override(config.clone(), || async {
                        run_with_mcp_session_id("mcp-session".to_string(), || async {
                            run_with_installation_id(Uuid::new_v4(), || async {
                                run_with_model_id("gpt-5.5".to_string(), || async {
                                    spawn_with_task_context(async {
                                        (
                                            get_task_session_key(),
                                            get_task_caller_cache_identity(),
                                            get_task_auth_override(),
                                            get_task_config_override(),
                                            get_task_mcp_session_id(),
                                            get_task_model_id(),
                                            get_task_installation_id(),
                                        )
                                    })
                                    .await
                                    .expect("detached task")
                                })
                                .await
                            })
                            .await
                        })
                        .await
                    })
                    .await
                })
                .await
            })
            .await
        })
        .await;

        assert_eq!(observed.0, Some(session_key));
        assert_eq!(observed.1.as_deref(), Some("stable-caller-scope"));
        let observed_auth = observed.2.expect("auth override");
        assert_eq!(observed_auth.api_key, auth.api_key);
        assert_eq!(observed_auth.workspace_id, auth.workspace_id);
        assert_eq!(observed_auth.project_id, auth.project_id);
        let observed_config = observed.3.expect("config override");
        assert_eq!(observed_config.search_limit, config.search_limit);
        assert_eq!(observed.4.as_deref(), Some("mcp-session"));
        assert_eq!(observed.5.as_deref(), Some("gpt-5.5"));
        assert!(observed.6.is_some());
    }
}

fn external_media_filename(external_url: &str, content_type: Option<&str>) -> String {
    let path = external_url
        .split(['?', '#'])
        .next()
        .unwrap_or(external_url)
        .trim_end_matches('/');
    let candidate = path.rsplit('/').next().unwrap_or("").trim();
    if !candidate.is_empty() && candidate.contains('.') {
        return candidate.to_string();
    }

    let content_type = content_type.unwrap_or("").to_ascii_lowercase();
    let extension = match content_type.as_str() {
        "image" | "photo" | "photos" => "png",
        "video" => "mp4",
        "audio" => "mp3",
        "document" | "doc" | "docs" => "pdf",
        "text" => "txt",
        _ => "bin",
    };
    format!("external-media.{}", extension)
}

/// Run a future under a per-request session-identity key.
///
/// The HTTP transport layer calls this in `auth_middleware` after decoding
/// the caller's credentials. Any code inside `f` — including every
/// `SessionManager` method call — reads back the same key via
/// `get_task_session_key()` so its in-memory state stays scoped to the
/// authenticated subject.
pub async fn run_with_session_key<F, Fut>(key: SessionKey, f: F) -> Fut::Output
where
    F: FnOnce() -> Fut,
    Fut: std::future::Future,
{
    TASK_SESSION_KEY.scope(key, f()).await
}

/// Run a future with the stable, opaque identity used by caller-sensitive
/// caches. HTTP installs this separately from the session key so mutable
/// session state remains isolated while immutable read results can be reused
/// across reconnects by the same authenticated principal.
pub async fn run_with_caller_cache_identity<F, Fut>(identity: String, f: F) -> Fut::Output
where
    F: FnOnce() -> Fut,
    Fut: std::future::Future,
{
    TASK_CALLER_CACHE_IDENTITY.scope(identity, f()).await
}

/// Read the current stable cache identity. Missing task-local state must be
/// treated as a cache bypass, never inferred from process configuration.
pub fn get_task_caller_cache_identity() -> Option<String> {
    TASK_CALLER_CACHE_IDENTITY
        .try_with(|identity| identity.clone())
        .ok()
}

/// Read the current task-local session identity, if any.
///
/// Returns `None` when a transport marker was never installed or was lost
/// across a detached task. Caller-sensitive caches must treat that as bypass;
/// stdio explicitly installs `SessionKey::Local` around its request loop.
pub fn get_task_session_key() -> Option<SessionKey> {
    TASK_SESSION_KEY.try_with(|k: &SessionKey| k.clone()).ok()
}

/// Resolve the current caller identity for response caches owned by this
/// shared client. Missing task-local state and anonymous HTTP both fail closed;
/// only the transport-installed `SessionKey::Local` marker opens the stdio
/// fast lane.
fn current_client_cache_identity() -> Option<String> {
    if let Some(identity) = get_task_caller_cache_identity() {
        return Some(identity);
    }
    client_cache_identity_for_session_key(get_task_session_key())
}

fn client_cache_identity_for_session_key(session_key: Option<SessionKey>) -> Option<String> {
    match session_key {
        None | Some(SessionKey::AnonymousHttp(_)) => None,
        Some(SessionKey::Local) => Some(local_stdio_cache_identity().to_string()),
        Some(key) => key.atlas_user_scope_token(),
    }
}

/// The client cache is process-local, but a nonce still makes the trusted
/// stdio identity explicit and prevents accidental reuse if these keys are
/// ever forwarded to a wider cache layer.
fn local_stdio_cache_identity() -> &'static str {
    static IDENTITY: OnceLock<String> = OnceLock::new();
    IDENTITY
        .get_or_init(|| format!("l:stdio:{}", Uuid::new_v4().simple()))
        .as_str()
}
use uuid::Uuid;

use crate::cache::{create_global_cache, ttl, CacheKey, GlobalCache};
