    /// Track a compliance event for analytics and agentic telemetry.
    pub async fn track_compliance_event(
        &self,
        mut request: ComplianceEventRequest,
    ) -> Result<ComplianceEventRecorded> {
        let config = self.config.read().await.clone();
        if request.workspace_id.is_none() {
            request.workspace_id = config.default_workspace_id;
        }
        if request.project_id.is_none() {
            request.project_id = config.default_project_id;
        }

        if request.workspace_id.is_none() {
            return Err(Error::Validation(
                "workspace_id required for compliance event".to_string(),
            ));
        }
        if request.model_id.trim().is_empty() {
            return Err(Error::Validation(
                "model_id required for compliance event".to_string(),
            ));
        }
        if request.harness_id.trim().is_empty() {
            return Err(Error::Validation(
                "harness_id required for compliance event".to_string(),
            ));
        }
        if request.rule_key.trim().is_empty() {
            return Err(Error::Validation(
                "rule_key required for compliance event".to_string(),
            ));
        }

        drop(config);
        self.post("/analytics/compliance/events", request).await
    }

    /// Simple URL encoding for query parameters.
    fn url_encode(s: &str) -> String {
        let mut result = String::with_capacity(s.len() * 3);
        for c in s.chars() {
            match c {
                'A'..='Z' | 'a'..='z' | '0'..='9' | '-' | '_' | '.' | '~' => {
                    result.push(c);
                }
                ' ' => {
                    result.push_str("%20");
                }
                _ => {
                    for byte in c.to_string().as_bytes() {
                        result.push_str(&format!("%{:02X}", byte));
                    }
                }
            }
        }
        result
    }

    fn append_client_cache_key_field(hasher: &mut Sha256, name: &str, value: Option<&[u8]>) {
        hasher.update((name.len() as u32).to_be_bytes());
        hasher.update(name.as_bytes());
        match value {
            Some(value) => {
                hasher.update([1]);
                hasher.update((value.len() as u64).to_be_bytes());
                hasher.update(value);
            }
            None => hasher.update([0]),
        }
    }

    fn caller_bound_cache_key(
        prefix: &str,
        domain: &str,
        caller_identity: &str,
        fields: &[(&str, Option<&[u8]>)],
    ) -> CacheKey {
        let mut hasher = Sha256::new();
        hasher.update((domain.len() as u64).to_be_bytes());
        hasher.update(domain.as_bytes());
        hasher.update(((fields.len() + 1) as u64).to_be_bytes());
        Self::append_client_cache_key_field(
            &mut hasher,
            "caller_identity",
            Some(caller_identity.as_bytes()),
        );
        for (name, value) in fields {
            Self::append_client_cache_key_field(&mut hasher, name, *value);
        }
        CacheKey::custom(format!("{}v2:{}", prefix, hex::encode(hasher.finalize())))
    }

    fn custom_json_cache_key(
        prefix: &str,
        domain: &str,
        caller_identity: &str,
        value: &serde_json::Value,
    ) -> CacheKey {
        let serialized = serde_json::to_vec(value).unwrap_or_else(|_| b"null".to_vec());
        Self::caller_bound_cache_key(
            prefix,
            domain,
            caller_identity,
            &[("request_body", Some(serialized.as_slice()))],
        )
    }

    fn fixed_cache_key(prefix: &str, domain: &str, caller_identity: &str) -> CacheKey {
        Self::caller_bound_cache_key(prefix, domain, caller_identity, &[])
    }

