    fn project_index_status_cache_key_for_checkout(
        caller_identity: &str,
        project_id: Uuid,
        checkout_scope: Option<&CheckoutRoutingScope>,
    ) -> CacheKey {
        let project_id = project_id.to_string();
        let installation_id = checkout_scope.map(|scope| scope.installation_id.to_string());
        let checkout_locator = checkout_scope.map(|scope| scope.checkout_locator.as_bytes());
        Self::caller_bound_cache_key(
            PROJECT_INDEX_STATUS_CACHE_PREFIX,
            "contextstream-client-project-index-status-cache-v3",
            caller_identity,
            &[
                ("project_id", Some(project_id.as_bytes())),
                (
                    "installation_id",
                    installation_id.as_deref().map(str::as_bytes),
                ),
                ("checkout_locator", checkout_locator),
            ],
        )
    }

