    fn capsule_locator_path<T: CapsuleLocatorInput>(
        &self,
        params: &T,
        extra_path: Option<&str>,
    ) -> Result<String> {
        let suffix = extra_path
            .map(|extra| format!("/{}", extra.trim_start_matches('/')))
            .unwrap_or_default();

        if let Some(capsule_id) = params.capsule_id() {
            let capsule_id =
                extract_capsule_id(capsule_id).unwrap_or_else(|| capsule_id.trim().to_string());
            return Ok(format!("/capsules/{}{}", capsule_id, suffix));
        }

        if let Some(token) = params.share_token().map(str::trim) {
            if let Some(capsule_id) = extract_capsule_id(token) {
                return Ok(format!("/capsules/{}{}", capsule_id, suffix));
            }
            if let Some(token) = extract_capsule_share_token(token) {
                return Ok(format!("/capsules/shares/{}{}", token, suffix));
            }
            return Ok(format!("/capsules/shares/{}{}", token, suffix));
        }

        if let Some(url) = params.url() {
            if let Some(token) = extract_capsule_share_token(url) {
                return Ok(format!("/capsules/shares/{}{}", token, suffix));
            }
            if let Some(capsule_id) = extract_capsule_id(url) {
                return Ok(format!("/capsules/{}{}", capsule_id, suffix));
            }
            return Err(Error::Validation(
                "Unsupported ContextCapsule locator URL".to_string(),
            ));
        }

        Err(Error::Validation(
            "capsule_id, share_token, or url is required".to_string(),
        ))
    }

    fn capsule_open_path(&self, params: &CapsuleOpenParams) -> Result<String> {
        if let Some(format) = params.format.as_deref() {
            if !matches!(format, "summary") {
                return Err(Error::Validation(
                    "open_capsule only supports JSON/summary responses; use capsule_context_doc for markdown/text or capsule_stream for ndjson"
                        .to_string(),
                ));
            }
        }

        let base = self.capsule_locator_path(params, None)?;
        let mut query = Vec::new();

        if matches!(params.format.as_deref(), Some("summary")) {
            query.push("format=summary".to_string());
        }
        if params.hydrate.unwrap_or(false) {
            query.push("hydrate=true".to_string());
        }

        if query.is_empty() {
            Ok(base)
        } else {
            Ok(format!("{}?{}", base, query.join("&")))
        }
    }

