    /// Explore search with server-side mode routing.
    ///
    /// Falls back to `/search/hybrid` on older API versions that do not expose
    /// `/search/explore`.
    pub async fn search_explore(&self, params: SearchParams) -> Result<SearchResponse> {
        let fallback_params = params.clone();
        let config = self.config.read().await;
        let mut body = params.with_defaults(&config, "hybrid");
        drop(config);

        if let Some(obj) = body.as_object_mut() {
            obj.insert("auto_mode".to_string(), serde_json::Value::Bool(true));
        }

        match self.post("/search/explore", body).await {
            Ok(response) => Ok(response),
            Err(err) if should_fallback_from_explore_error(&err) => {
                self.search_hybrid(fallback_params).await
            }
            Err(err) => Err(err),
        }
    }

