    /// Report an idempotent outcome for a caller-owned, explicitly opted-in
    /// code-reranker learning observation. The API resolves the request UUID
    /// together with authenticated user/workspace/project scope and never
    /// accepts raw database impression IDs.
    pub async fn record_code_rerank_outcome(
        &self,
        params: CodeRerankOutcomeParams,
    ) -> Result<CodeRerankOutcomeResponse> {
        if !params.learning_opt_in {
            return Err(Error::Validation(
                "learning_opt_in=true is required to report a reranker outcome".to_string(),
            ));
        }
        if params.learning_request_id.is_nil() || params.event_id.is_nil() {
            return Err(Error::Validation(
                "learning_request_id and event_id must be non-nil UUIDs".to_string(),
            ));
        }
        if params.workspace_id.is_nil() || params.project_id.is_nil() {
            return Err(Error::Validation(
                "workspace_id and project_id must be non-nil UUIDs".to_string(),
            ));
        }
        let candidate_id = params
            .candidate_id
            .as_deref()
            .map(str::trim)
            .filter(|candidate| !candidate.is_empty());
        if params.candidate_id.is_some()
            && candidate_id.is_none_or(|candidate| candidate.chars().count() > 4_096)
        {
            return Err(Error::Validation(
                "candidate_id must contain 1 to 4096 characters".to_string(),
            ));
        }
        if params.outcome_type.requires_candidate() && candidate_id.is_none() {
            return Err(Error::Validation(
                "candidate_id is required for this outcome type".to_string(),
            ));
        }
        if let Some(rank) = params.observed_rank {
            if candidate_id.is_none() || !(1..=100).contains(&rank) {
                return Err(Error::Validation(
                    "observed_rank requires candidate_id and must be between 1 and 100".to_string(),
                ));
            }
        }
        if params
            .confidence
            .is_some_and(|confidence| !confidence.is_finite() || !(0.0..=1.0).contains(&confidence))
        {
            return Err(Error::Validation(
                "confidence must be finite and between 0 and 1".to_string(),
            ));
        }
        self.post("/search/rerank/outcomes", params).await
    }

    async fn search_with_cache(
        &self,
        endpoint: &str,
        body: serde_json::Value,
    ) -> Result<SearchResponse> {
        let cacheable = Self::should_cache_search_response(&body);
        let cache_key = current_client_cache_identity()
            .map(|caller| Self::search_cache_key(&caller, endpoint, &body));
        if cacheable {
            if let Some(cached) = self.cached_response(cache_key.as_ref()) {
                return serde_json::from_value(cached).map_err(|e| {
                    Error::Validation(format!("Failed to parse cached search response: {}", e))
                });
            }
        }
        let result: SearchResponse = self.post(endpoint, body).await?;
        if cacheable {
            if let Ok(serialized) = serde_json::to_value(&result) {
                self.cache_response(cache_key, serialized, SEARCH_CACHE_TTL);
            }
        }
        Ok(result)
    }
    // =========================================================================
    // Context / Session
    // =========================================================================

    /// Get smart context.
    /// Keep timeout below common MCP tool-call budgets (e.g. 60s in Codex) so
    /// callers get a structured timeout/fallback instead of a hard client-side deadline.
    ///
    /// Override with `MCP_CONTEXT_SMART_TIMEOUT_SECS` (5-55). Defaults to 15s.
    /// The server has a 25s overall timeout; 15s on the client is enough to catch
    /// the vast majority of responses while enabling faster fallback on slow turns.
    pub async fn context_smart(&self, params: ContextParams) -> Result<ContextResponse> {
        let config = self.config.read().await;
        let body = params.with_defaults(&config);
        drop(config);
        let timeout_secs = std::env::var("MCP_CONTEXT_SMART_TIMEOUT_SECS")
            .ok()
            .and_then(|v| v.trim().parse::<u64>().ok())
            .filter(|v| (5..=55).contains(v))
            .unwrap_or(15);

        self.post_with_options(
            "/context/smart",
            body,
            RequestOptions {
                timeout: Some(Duration::from_secs(timeout_secs)),
                retries: Some(0),
                ..Default::default()
            },
        )
        .await
    }

    /// Get fast cached context via /context/hook (Redis-cached, ~20-50ms).
    /// Returns rules and preferences without LLM analysis.
    /// Use this for lightweight context needs instead of the full context_smart() pipeline.
    /// Returns the raw JSON response; callers should extract `data.context` as a string.
    pub async fn context_fast(
        &self,
        workspace_id: Option<Uuid>,
        project_id: Option<Uuid>,
        session_id: Option<&str>,
        user_message: Option<&str>,
    ) -> Result<serde_json::Value> {
        self.context_fast_for_checkout(workspace_id, project_id, session_id, user_message, None)
            .await
    }

    /// Fast context scoped to the active checkout. The folder is converted to
    /// an opaque installation-bound locator before the request is sent.
    pub async fn context_fast_for_checkout(
        &self,
        workspace_id: Option<Uuid>,
        project_id: Option<Uuid>,
        session_id: Option<&str>,
        user_message: Option<&str>,
        folder_path: Option<&str>,
    ) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let (ws_id, proj_id) = scope_ids_with_defaults(workspace_id, project_id, &config);
        drop(config);

        let mut body = serde_json::json!({});
        if let Some(id) = ws_id {
            body["workspace_id"] = serde_json::json!(id.to_string());
        }
        if let Some(id) = proj_id {
            body["project_id"] = serde_json::json!(id.to_string());
        }
        if let Some(msg) = user_message {
            body["user_message"] = serde_json::json!(msg);
        }
        if let Some(sid) = session_id {
            body["session_id"] = serde_json::json!(sid);
        }
        if let Some(scope) = folder_path.and_then(Self::checkout_routing_scope) {
            body["installation_id"] = serde_json::json!(scope.installation_id);
            body["checkout_locator"] = serde_json::json!(scope.checkout_locator);
        }

        self.post_with_options(
            "/context/hook",
            body,
            RequestOptions {
                timeout: Some(Duration::from_secs(2)),
                retries: Some(1),
                ..Default::default()
            },
        )
        .await
    }

