    /// Best-effort activation delivery. It is intentionally short-timeout,
    /// retry-bounded, and detached by callers so analytics can never block a
    /// tool result. A 404 from an older API is logged at debug level only.
    pub async fn report_activation_event_best_effort(
        &self,
        payload: crate::activation::ActivationEventPayload,
    ) {
        let result: Result<serde_json::Value> = self
            .request(
                "POST",
                "/activation/events",
                Some(payload),
                Some(RequestOptions {
                    timeout: Some(Duration::from_secs(3)),
                    retries: Some(1),
                    ..Default::default()
                }),
            )
            .await;
        if let Err(error) = result {
            debug!(%error, "activation telemetry delivery skipped");
        }
    }

    pub fn spawn_first_mcp_action(
        &self,
        workspace_id: Option<Uuid>,
        project_id: Option<Uuid>,
        session_id: Option<String>,
        tool_name: &str,
        operation_category: &str,
    ) {
        let Some(payload) = crate::activation::first_action_event(
            workspace_id,
            project_id,
            session_id,
            tool_name,
            operation_category,
        ) else {
            return;
        };
        let client = self.clone();
        tokio::spawn(async move {
            client.report_activation_event_best_effort(payload).await;
        });
    }

    pub fn spawn_activation_failure(
        &self,
        workspace_id: Option<Uuid>,
        project_id: Option<Uuid>,
        session_id: Option<String>,
        stage: &str,
        error: &Error,
    ) {
        let (error_code, http_status) = match error {
            Error::Http { status, code, .. } => (code.as_str().to_ascii_lowercase(), Some(*status)),
            _ => (error.code().as_str().to_ascii_lowercase(), None),
        };
        let Some(payload) = crate::activation::failure_event(
            workspace_id,
            project_id,
            session_id,
            stage,
            &error_code,
            error.is_retryable(),
            http_status,
        ) else {
            return;
        };
        let client = self.clone();
        tokio::spawn(async move {
            client.report_activation_event_best_effort(payload).await;
        });
    }

