    fn normalize_session_capture_original_type(event_type: Option<&str>) -> String {
        event_type
            .map(|value| value.trim().to_ascii_lowercase().replace(['-', ' '], "_"))
            .map(|value| match value.as_str() {
                "" | "manual_note" | "manualnote" | "note" | "memory" | "general"
                | "uncategorized" | "uncatergorized" => "uncategorized".to_string(),
                "commandexecution" => "command_execution".to_string(),
                "fileoperation" => "file_operation".to_string(),
                _ => value,
            })
            .unwrap_or_else(|| "uncategorized".to_string())
    }

    fn map_session_capture_api_event_type(normalized_original_type: &str) -> String {
        match normalized_original_type {
            "conversation" => "chat".to_string(),
            "task" => "task".to_string(),
            "plan" => "plan".to_string(),
            "bug" | "feature" => "ticket".to_string(),
            "meeting" => "meeting".to_string(),
            "chat" => "chat".to_string(),
            "ticket" => "ticket".to_string(),
            "doc" | "document" => "doc".to_string(),
            "decision" | "preference" | "insight" | "uncategorized" | "implementation"
            | "operation" | "command_execution" | "file_operation" | "correction" | "lesson"
            | "warning" | "frustration" | "session_snapshot" => {
                normalized_original_type.to_string()
            }
            _ => "uncategorized".to_string(),
        }
    }

    /// Capture session state (creates a memory event).
    pub async fn session_capture(&self, params: SessionCaptureParams) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let (ws_id, proj_id) =
            scope_ids_with_defaults(params.workspace_id, params.project_id, &config);
        drop(config);

        let ws_id = ws_id.ok_or_else(|| {
            Error::Config(
                "workspace_id is required for session capture but was not set. Run init first."
                    .into(),
            )
        })?;

        let normalized_original_type =
            Self::normalize_session_capture_original_type(params.event_type.as_deref());
        let api_event_type = Self::map_session_capture_api_event_type(&normalized_original_type);

        let mut body = strip_nulls(serde_json::json!({
            "workspace_id": ws_id,
            "project_id": proj_id,
            "event_type": api_event_type,
            "title": params.title,
            "content": params.content,
            "metadata": {
                "original_type": normalized_original_type,
                "importance": params.importance.as_deref().unwrap_or("medium"),
                "source": "mcp_auto_capture"
            }
        }));
        if let Some(session_id) = params.session_id {
            body["session_id"] = serde_json::json!(session_id);
        }
        if let Some(provenance) = params.provenance {
            body["provenance"] = provenance;
        }
        if let Some(code_refs) = params.code_refs {
            body["code_refs"] = serde_json::Value::Array(code_refs);
        }
        if let Some(tags) = params.tags {
            body["tags"] = serde_json::json!(tags);
        }

        let result = self.post("/memory/events", body).await?;
        self.invalidate_memory_read_caches();
        Ok(result)
    }

    /// Capture a local VCS event (commit/push/checkout/merge) observed by the
    /// managed git hooks.
    ///
    /// Posts to `/workspaces/{workspace}/vcs/local-events`; the server records
    /// the raw VCS event, mirrors it into memory, and dedupes by
    /// `provider_event_id` (the commit/push sha) so a git-hook event and a
    /// Claude-Bash fallback for the same operation collapse into one row. The
    /// workspace scope must be resolvable (explicit param or session default),
    /// otherwise this returns a config error without making a request.
    pub async fn capture_vcs_local_event(
        &self,
        params: CaptureVcsLocalEventParams,
    ) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let (ws_id, proj_id) =
            scope_ids_with_defaults(params.workspace_id, params.project_id, &config);
        drop(config);

        let ws_id = ws_id.ok_or_else(|| {
            Error::Config(
                "workspace_id is required to capture a local VCS event but was not set. Run init first."
                    .into(),
            )
        })?;

        let body = vcs_local_event_body(params, proj_id)?;

        let result = self
            .post(&format!("/workspaces/{}/vcs/local-events", ws_id), body)
            .await?;
        self.invalidate_memory_read_caches();
        Ok(result)
    }

    /// Recall session state (searches memory).
    pub async fn session_recall(&self, params: SessionRecallParams) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let cache_body = params.clone().with_defaults(&config);
        drop(config);
        let cache_key = current_client_cache_identity()
            .map(|caller| Self::session_recall_cache_key(&caller, &cache_body));
        if let Some(cached) = self.cached_response(cache_key.as_ref()) {
            return Ok(cached);
        }

        let result: serde_json::Value = self.post("/session/recall", cache_body).await?;
        self.cache_response(cache_key, result.clone(), MEMORY_SEARCH_CACHE_TTL);
        Ok(result)
    }

    /// Capture a lesson learned.
    pub async fn session_capture_lesson(
        &self,
        params: SessionCaptureLessonParams,
    ) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let (ws_id, proj_id) =
            scope_ids_with_defaults(params.workspace_id, params.project_id, &config);
        drop(config);

        // Format lesson content
        let content = format!(
            "## {}\n**Severity:** {}\n### Trigger\n{}\n### Impact\n{}\n### Prevention\n{}",
            params.title,
            params.severity.as_deref().unwrap_or("medium"),
            params.trigger,
            params.impact,
            params.prevention
        );

        let severity = params
            .severity
            .clone()
            .unwrap_or_else(|| "medium".to_string());
        let category = params.category.clone();
        let mut tags = vec![
            "lesson".to_string(),
            "lesson_system".to_string(),
            format!("severity:{}", severity),
        ];
        if let Some(cat) = category.clone() {
            tags.push(cat);
        }
        if let Some(keywords) = params.keywords.clone() {
            tags.extend(keywords);
        }

        let body = strip_nulls(serde_json::json!({
            "workspace_id": ws_id,
            "project_id": proj_id,
            "event_type": "lesson",
            "title": params.title,
            "content": content,
            "metadata": {
                "original_type": "lesson",
                "severity": severity,
                "category": category,
                "tags": tags,
                "source": "lesson_capture"
            }
        }));

        let result = self.post("/memory/events", body).await?;
        self.invalidate_memory_read_caches();
        Ok(result)
    }

    /// Get lessons learned.
    ///
    /// Uses the events listing endpoint with `event_type=lesson` to reliably
    /// return all captured lessons.  The previous approach relied on semantic
    /// search with hard-coded keywords which silently returned empty results
    /// when the search index didn't match.
    ///
    /// When the caller supplies a `query`, we first try a targeted memory
    /// search so results are relevance-ranked.  If that yields nothing we
    /// fall back to the listing endpoint.  When no query is given we skip
    /// the search entirely and go straight to the listing.
    pub async fn session_get_lessons(
        &self,
        params: SessionGetLessonsParams,
    ) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let (ws_id, proj_id) =
            scope_ids_with_defaults(params.workspace_id, params.project_id, &config);
        drop(config);

        let requested_limit = params.limit.unwrap_or(10).max(1);
        let fetch_limit = requested_limit.saturating_mul(2).min(100);

        // When a query is supplied, search only lesson-related memory items first
        // so results come back ranked without relying on legacy prompt stuffing.
        if let Some(ref q) = params.query {
            let search_params = MemorySearchParams {
                query: q.trim().to_string(),
                workspace_id: ws_id,
                project_id: proj_id,
                node_type: Some("lesson".to_string()),
                limit: Some(fetch_limit),
                ..Default::default()
            };
            match self.search_memory(search_params).await {
                Ok(search_result) => {
                    // If the search returned items, use those.
                    let has_items = search_result
                        .get("data")
                        .and_then(|d| d.get("items"))
                        .and_then(|i| i.as_array())
                        .map(|a| !a.is_empty())
                        .unwrap_or(false)
                        || search_result
                            .get("results")
                            .and_then(|r| r.as_array())
                            .map(|a| !a.is_empty())
                            .unwrap_or(false)
                        || search_result
                            .get("items")
                            .and_then(|i| i.as_array())
                            .map(|a| !a.is_empty())
                            .unwrap_or(false);

                    if has_items {
                        return Ok(search_result);
                    }
                }
                Err(err) => {
                    // Keep running fallback so lesson retrieval still works when
                    // memory search endpoints are unavailable.
                    warn!(
                        "session_get_lessons memory search failed, falling back to list_memory_events: {}",
                        err
                    );
                }
            }
        }

        // Primary path: list lesson events directly via the events endpoint.
        self.list_memory_events(
            ws_id,
            proj_id,
            Some("lesson".to_string()),
            Some(fetch_limit),
        )
        .await
    }

