    /// Compress chat history by extracting patterns and storing as memory events.
    pub async fn session_compress(
        &self,
        params: SessionCompressParams,
    ) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let (ws_id, proj_id) =
            scope_ids_with_defaults(params.workspace_id, params.project_id, &config);
        drop(config);

        let extract_types = params.extract_types.unwrap_or_else(|| {
            vec![
                "decisions".into(),
                "preferences".into(),
                "insights".into(),
                "tasks".into(),
                "code_patterns".into(),
            ]
        });

        // Extract patterns from chat content line-by-line
        let mut decisions = Vec::new();
        let mut preferences = Vec::new();
        let mut insights = Vec::new();
        let mut tasks = Vec::new();
        let mut code_patterns = Vec::new();

        for line in params.content.lines() {
            let lower = line.to_lowercase();
            let trimmed = line.trim();
            if trimmed.is_empty() {
                continue;
            }

            if extract_types.iter().any(|t| t == "decisions")
                && (lower.contains("decided to")
                    || lower.contains("decision:")
                    || lower.contains("we'll use")
                    || lower.contains("going with")
                    || lower.contains("chose "))
            {
                decisions.push(trimmed.to_string());
            }

            if extract_types.iter().any(|t| t == "preferences")
                && (lower.contains("prefer")
                    || lower.contains("i like")
                    || lower.contains("always use")
                    || lower.contains("don't use")
                    || lower.contains("never use"))
            {
                preferences.push(trimmed.to_string());
            }

            if extract_types.iter().any(|t| t == "tasks")
                && (lower.contains("todo:")
                    || lower.contains("task:")
                    || lower.contains("need to")
                    || lower.contains("should implement")
                    || lower.contains("will add"))
            {
                tasks.push(trimmed.to_string());
            }

            if extract_types.iter().any(|t| t == "insights")
                && (lower.contains("learned that")
                    || lower.contains("realized")
                    || lower.contains("found out")
                    || lower.contains("discovered")
                    || lower.contains("important:")
                    || lower.contains("note:"))
            {
                insights.push(trimmed.to_string());
            }

            if extract_types.iter().any(|t| t == "code_patterns")
                && (lower.contains("pattern:")
                    || lower.contains("convention:")
                    || lower.contains("style:")
                    || lower.contains("always format")
                    || lower.contains("naming convention"))
            {
                code_patterns.push(trimmed.to_string());
            }
        }

        // Store extracted items as memory events (max 5 per category)
        let mut events_created: i64 = 0;

        for decision in decisions.iter().take(5) {
            let body = strip_nulls(serde_json::json!({
                "workspace_id": ws_id,
                "project_id": proj_id,
                "event_type": "decision",
                "title": &decision[..decision.len().min(100)],
                "content": decision,
                "metadata": { "importance": "medium", "source": "compress_extract" }
            }));
            if self
                .post::<serde_json::Value, _>("/memory/events", body)
                .await
                .is_ok()
            {
                events_created += 1;
            }
        }

        for pref in preferences.iter().take(5) {
            let body = strip_nulls(serde_json::json!({
                "workspace_id": ws_id,
                "project_id": proj_id,
                "event_type": "uncategorized",
                "title": &pref[..pref.len().min(100)],
                "content": pref,
                "metadata": { "original_type": "preference", "importance": "medium", "source": "compress_extract" }
            }));
            if self
                .post::<serde_json::Value, _>("/memory/events", body)
                .await
                .is_ok()
            {
                events_created += 1;
            }
        }

        for insight in insights.iter().take(5) {
            let body = strip_nulls(serde_json::json!({
                "workspace_id": ws_id,
                "project_id": proj_id,
                "event_type": "uncategorized",
                "title": &insight[..insight.len().min(100)],
                "content": insight,
                "metadata": { "original_type": "insight", "importance": "medium", "source": "compress_extract" }
            }));
            if self
                .post::<serde_json::Value, _>("/memory/events", body)
                .await
                .is_ok()
            {
                events_created += 1;
            }
        }

        for task in tasks.iter().take(5) {
            let body = strip_nulls(serde_json::json!({
                "workspace_id": ws_id,
                "project_id": proj_id,
                "event_type": "uncategorized",
                "title": &task[..task.len().min(100)],
                "content": task,
                "metadata": { "original_type": "task", "importance": "medium", "source": "compress_extract" }
            }));
            if self
                .post::<serde_json::Value, _>("/memory/events", body)
                .await
                .is_ok()
            {
                events_created += 1;
            }
        }

        for pattern in code_patterns.iter().take(5) {
            let body = strip_nulls(serde_json::json!({
                "workspace_id": ws_id,
                "project_id": proj_id,
                "event_type": "uncategorized",
                "title": &pattern[..pattern.len().min(100)],
                "content": pattern,
                "metadata": { "original_type": "code_pattern", "importance": "medium", "source": "compress_extract" }
            }));
            if self
                .post::<serde_json::Value, _>("/memory/events", body)
                .await
                .is_ok()
            {
                events_created += 1;
            }
        }

        Ok(serde_json::json!({
            "status": "compressed",
            "events_created": events_created,
            "extracted": {
                "decisions": decisions.len(),
                "preferences": preferences.len(),
                "insights": insights.len(),
                "tasks": tasks.len(),
                "code_patterns": code_patterns.len(),
            }
        }))
    }

    /// Get changes since timestamp (composite: fetches recent memory events).
    pub async fn session_delta(&self, params: SessionDeltaParams) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let (ws_id, proj_id) =
            scope_ids_with_defaults(params.workspace_id, params.project_id, &config);
        drop(config);

        // Delta is a composite operation - get recent events since the timestamp
        let events = self
            .list_memory_events(ws_id, proj_id, None, params.limit.or(Some(20)))
            .await?;

        // Filter and count by type
        let items = events
            .get("items")
            .cloned()
            .unwrap_or(serde_json::json!([]));
        let items_arr = items.as_array().cloned().unwrap_or_default();

        let mut new_decisions = 0;
        let mut new_memory = 0;
        for item in &items_arr {
            if let Some(event_type) = item.get("event_type").and_then(|v| v.as_str()) {
                if event_type == "decision" {
                    new_decisions += 1;
                } else {
                    new_memory += 1;
                }
            }
        }

        Ok(serde_json::json!({
            "new_decisions": new_decisions,
            "new_memory": new_memory,
            "items": items_arr,
            "since": params.since
        }))
    }

    /// Context-enriched smart search.
    pub async fn session_smart_search(
        &self,
        params: SessionSmartSearchParams,
    ) -> Result<serde_json::Value> {
        let SessionSmartSearchParams {
            query,
            include_related,
            include_decisions,
            limit,
            workspace_id,
            project_id,
        } = params;

        let config = self.config.read().await;
        let (ws_id, proj_id) = scope_ids_with_defaults(workspace_id, project_id, &config);
        drop(config);

        if let Some(node_type) = infer_memory_query_node_type(&query) {
            let result = self
                .search_memory(MemorySearchParams {
                    query: query.clone(),
                    workspace_id: ws_id,
                    project_id: proj_id,
                    node_type: Some(node_type.clone()),
                    limit,
                    ..Default::default()
                })
                .await?;

            return Ok(build_smart_search_response_from_memory_search(
                &query,
                include_related,
                include_decisions,
                &node_type,
                result,
            ));
        }

        let body = strip_nulls(serde_json::json!({
            "query": query,
            "include_related": include_related,
            "include_decisions": include_decisions,
            "limit": limit,
            "workspace_id": ws_id,
            "project_id": proj_id,
        }));
        let result = self.post("/session/smart-search", body).await?;
        Ok(normalize_session_smart_search_response(result))
    }

    /// Trace decision provenance.
    pub async fn session_decision_trace(
        &self,
        params: SessionDecisionTraceParams,
    ) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let query = params.query.clone();
        let limit = params.limit.unwrap_or(10).max(1);
        let (workspace_id, project_id) =
            scope_ids_with_defaults(params.workspace_id, params.project_id, &config);
        let body = params.with_defaults(&config);
        drop(config);

        let query_terms: Vec<String> = query
            .to_lowercase()
            .split_whitespace()
            .filter(|term| term.len() > 2)
            .map(|term| term.to_string())
            .collect();

        let build_fallback = |reason: &str, hint: String, decisions: Vec<serde_json::Value>| {
            let total = decisions.len();
            serde_json::json!({
                "decisions": decisions,
                "total": total,
                "fallback_reason": reason,
                "hint": hint
            })
        };

        let fallback_from_events = || async {
            let events = self
                .list_memory_events(
                    workspace_id,
                    project_id,
                    None,
                    Some(limit.saturating_mul(5)),
                )
                .await
                .unwrap_or_else(|_| serde_json::json!({ "items": [] }));
            let items = events
                .get("items")
                .and_then(|value| value.as_array())
                .cloned()
                .unwrap_or_default();

            let mut matched: Vec<serde_json::Value> = items
                .into_iter()
                .filter(|item| {
                    let event_type = item
                        .get("event_type")
                        .and_then(|value| value.as_str())
                        .unwrap_or("")
                        .to_lowercase();
                    let metadata_original = item
                        .get("metadata")
                        .and_then(|meta| meta.get("original_type"))
                        .and_then(|value| value.as_str())
                        .unwrap_or("")
                        .to_lowercase();
                    event_type == "decision" || metadata_original == "decision"
                })
                .filter(|item| {
                    if query_terms.is_empty() {
                        return true;
                    }
                    let haystack = format!(
                        "{} {}",
                        item.get("title")
                            .and_then(|value| value.as_str())
                            .unwrap_or(""),
                        item.get("content")
                            .and_then(|value| value.as_str())
                            .unwrap_or("")
                    )
                    .to_lowercase();
                    query_terms.iter().any(|term| haystack.contains(term))
                })
                .collect();

            matched.truncate(limit as usize);
            matched
        };

        match self
            .post::<serde_json::Value, _>("/memory/search/decisions/trace", body)
            .await
        {
            Ok(result) => {
                let decisions = result
                    .get("decisions")
                    .and_then(|value| value.as_array())
                    .cloned()
                    .or_else(|| {
                        result
                            .get("data")
                            .and_then(|value| value.get("decisions"))
                            .and_then(|value| value.as_array())
                            .cloned()
                    })
                    .unwrap_or_default();

                if decisions.is_empty() {
                    let fallback = fallback_from_events().await;
                    if !fallback.is_empty() {
                        return Ok(build_fallback(
                            "api_empty_result",
                            "Decision trace used event listing fallback because the API returned no results.".to_string(),
                            fallback,
                        ));
                    }
                }
                Ok(result)
            }
            Err(err) => {
                let lower = err.to_string().to_lowercase();
                let is_timeout = lower.contains("timeout") || lower.contains("embedding timed out");
                let fallback = fallback_from_events().await;
                let reason = if is_timeout {
                    "embedding_timeout"
                } else {
                    "api_error"
                };
                let hint = if is_timeout {
                    "Decision trace fell back to event matching due to embedding timeout."
                        .to_string()
                } else {
                    format!(
                        "Decision trace used event fallback after API error: {}",
                        err
                    )
                };
                Ok(build_fallback(reason, hint, fallback))
            }
        }
    }

