    /// List suggested rules.
    /// Endpoint: GET /suggested-rules (matching TypeScript)
    pub async fn list_suggested_rules(
        &self,
        params: ListSuggestedRulesParams,
    ) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let ws_id = params.workspace_id.or(config.default_workspace_id);
        let proj_id = params.project_id.or(config.default_project_id);
        drop(config);

        let mut query_params = vec![];
        if let Some(id) = ws_id {
            query_params.push(format!("workspace_id={}", id));
        }
        if let Some(id) = proj_id {
            query_params.push(format!("project_id={}", id));
        }
        if let Some(c) = params.min_confidence {
            query_params.push(format!("min_confidence={}", c));
        }
        // Typed envelope: `source_lesson_ids` per rule plus `native_guidance`.
        query_params.push("format=envelope".to_string());
        let path = format!("/suggested-rules?{}", query_params.join("&"));

        match self.get::<serde_json::Value>(&path).await {
            Ok(result) => Ok(result),
            Err(_) => Ok(serde_json::json!({
                "rules": [],
                "message": "Suggested rules feature not available"
            })),
        }
    }

    /// Take action on a suggested rule.
    /// Endpoint: POST /suggested-rules/{rule_id}/action (matching TypeScript)
    pub async fn suggested_rule_action(
        &self,
        params: SuggestedRuleActionParams,
    ) -> Result<serde_json::Value> {
        let path = format!("/suggested-rules/{}/action", params.rule_id);
        let body = serde_json::json!({
            "action": params.rule_action,
            "modified_instruction": params.modified_instruction,
        });
        let body = strip_nulls(body);
        match self.post::<serde_json::Value, _>(&path, &body).await {
            Ok(result) => Ok(result),
            Err(_) => Ok(serde_json::json!({
                "success": false,
                "message": "Suggested rules feature not available"
            })),
        }
    }

    /// Get suggested rules stats.
    /// Endpoint: GET /suggested-rules/stats (matching TypeScript)
    pub async fn suggested_rules_stats(
        &self,
        workspace_id: Option<Uuid>,
    ) -> Result<serde_json::Value> {
        let mut query_params = vec![];
        if let Some(id) = workspace_id {
            query_params.push(format!("workspace_id={}", id));
        }
        let path = if query_params.is_empty() {
            "/suggested-rules/stats".to_string()
        } else {
            format!("/suggested-rules/stats?{}", query_params.join("&"))
        };

        match self.get::<serde_json::Value>(&path).await {
            Ok(result) => Ok(result),
            Err(_) => Ok(serde_json::json!({
                "total_suggested": 0,
                "accepted": 0,
                "rejected": 0,
                "pending": 0,
                "message": "Suggested rules stats not available"
            })),
        }
    }

