    /// Search memory.
    pub async fn search_memory(&self, params: MemorySearchParams) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let body = params.with_defaults(&config);
        drop(config);
        let cache_key = current_client_cache_identity()
            .map(|caller| Self::memory_search_cache_key(&caller, &body));
        if let Some(cached) = self.cached_response(cache_key.as_ref()) {
            return Ok(cached);
        }

        // `reqwest::RequestBuilder::timeout` is per attempt. Wrap the complete
        // request future as well so the exceptional one-time 403 session
        // refresh replay cannot turn a six-second interactive contract into
        // two independent six-second waits.
        let result: serde_json::Value = tokio::time::timeout(
            MEMORY_SEARCH_REQUEST_TIMEOUT,
            self.request(
                "POST",
                "/memory/search",
                Some(body),
                Some(RequestOptions {
                    timeout: Some(MEMORY_SEARCH_REQUEST_TIMEOUT),
                    retries: Some(0),
                    ..Default::default()
                }),
            ),
        )
        .await
        .map_err(|_| Error::Timeout(MEMORY_SEARCH_REQUEST_TIMEOUT.as_secs()))??;
        if !Self::memory_search_response_is_degraded(&result) {
            self.cache_response(cache_key, result.clone(), MEMORY_SEARCH_CACHE_TTL);
        }
        Ok(result)
    }

    /// List decision summaries directly from the dedicated decisions endpoint.
    pub async fn list_memory_decisions(
        &self,
        workspace_id: Option<Uuid>,
        project_id: Option<Uuid>,
        query: Option<String>,
        category: Option<String>,
        limit: Option<i64>,
    ) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let (ws_id, proj_id) = scope_ids_with_defaults(workspace_id, project_id, &config);
        let ws_id = ws_id.ok_or_else(|| {
            Error::Validation("workspace_id is required for decisions".to_string())
        })?;
        drop(config);

        let mut params = vec![format!("workspace_id={}", ws_id)];
        if let Some(id) = proj_id {
            params.push(format!("project_id={}", id));
        }
        if let Some(query) = query.as_deref().map(str::trim).filter(|s| !s.is_empty()) {
            params.push(format!("query={}", urlencoding::encode(query)));
        }
        if let Some(category) = category.as_deref().map(str::trim).filter(|s| !s.is_empty()) {
            params.push(format!("category={}", urlencoding::encode(category)));
        }
        if let Some(limit) = limit {
            params.push(format!("limit={}", limit));
        }

        let path = format!("/memory/decisions?{}", params.join("&"));
        let results: Vec<serde_json::Value> = self.get(&path).await?;
        Ok(serde_json::json!({
            "results": results,
            "total": results.len(),
            "direct": true
        }))
    }

