    /// Supersede a memory node.
    /// Supersede a memory node (3-step process matching TypeScript):
    /// 1. Get existing node
    /// 2. Create new replacement node with updated content
    /// 3. Mark old node as superseded by new node
    pub async fn supersede_memory_node(
        &self,
        node_id: Uuid,
        params: SupersedeMemoryNodeParams,
    ) -> Result<serde_json::Value> {
        // Step 1: Get existing node
        let existing_raw = self.get_memory_node(node_id).await?;
        let existing = unwrap_api_response(existing_raw);

        let workspace_id = existing
            .get("workspace_id")
            .and_then(|v| v.as_str())
            .and_then(|s| Uuid::parse_str(s).ok());
        if workspace_id.is_none() {
            return Err(Error::Validation(
                "Failed to load existing node before superseding".to_string(),
            ));
        }
        let project_id = existing
            .get("project_id")
            .and_then(|v| v.as_str())
            .and_then(|s| Uuid::parse_str(s).ok());
        let node_type = existing
            .get("node_type")
            .and_then(|v| v.as_str())
            .unwrap_or("Note")
            .to_string();
        let title = existing
            .get("summary")
            .and_then(|v| v.as_str())
            .unwrap_or("Superseded node")
            .to_string();

        // Step 2: Create new replacement node with updated content
        let create_params = CreateMemoryNodeParams {
            node_type,
            title,
            content: Some(params.new_content),
            workspace_id,
            project_id,
            metadata: None,
        };
        let created_raw = self.create_memory_node(create_params).await?;
        let created = unwrap_api_response(created_raw);
        let new_id = created.get("id").and_then(|v| v.as_str()).ok_or_else(|| {
            Error::Validation("Failed to create replacement node for supersede".to_string())
        })?;

        // Step 3: Mark old node as superseded by new node
        let body = serde_json::json!({ "superseded_by": new_id });
        let _: serde_json::Value = self
            .post(&format!("/memory/nodes/{}/supersede", node_id), body)
            .await?;

        Ok(serde_json::json!({
            "status": "superseded",
            "old_node_id": node_id.to_string(),
            "new_node_id": new_id,
        }))
    }

