    /// List docs.
    fn build_docs_path(
        workspace_id: Option<Uuid>,
        project_id: Option<Uuid>,
        doc_type: Option<String>,
        is_personal: Option<bool>,
        query: Option<String>,
        limit: Option<i64>,
    ) -> String {
        let mut path = "/docs".to_string();
        let mut params = vec![];
        if let Some(id) = workspace_id {
            params.push(format!("workspace_id={}", id));
        }
        if let Some(id) = project_id {
            params.push(format!("project_id={}", id));
        }
        if let Some(t) = doc_type {
            params.push(format!("doc_type={}", Self::url_encode(&t)));
        }
        if let Some(p) = is_personal {
            params.push(format!("is_personal={}", p));
        }
        if let Some(q) = query.filter(|q| !q.trim().is_empty()) {
            params.push(format!("query={}", Self::url_encode(q.trim())));
        }
        if let Some(l) = limit {
            params.push(format!("per_page={}", l.clamp(1, 100)));
        }
        if !params.is_empty() {
            path = format!("{}?{}", path, params.join("&"));
        }
        path
    }

    /// List docs.
    pub async fn list_docs(
        &self,
        workspace_id: Option<Uuid>,
        project_id: Option<Uuid>,
        doc_type: Option<String>,
        is_personal: Option<bool>,
        query: Option<String>,
        limit: Option<i64>,
    ) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let (ws_id, proj_id) = scope_ids_with_defaults(workspace_id, project_id, &config);
        drop(config);

        let cache_key = current_client_cache_identity().map(|caller| {
            Self::docs_list_cache_key(
                &caller,
                ws_id,
                proj_id,
                doc_type.as_deref(),
                is_personal,
                query.as_deref(),
                limit,
            )
        });
        let path = Self::build_docs_path(ws_id, proj_id, doc_type, is_personal, query, limit);
        if let Some(cached) = self.cached_response(cache_key.as_ref()) {
            return Ok(cached);
        }

        let result: serde_json::Value = self.get(&path).await?;
        self.cache_response(cache_key, result.clone(), DOC_LOOKUP_CACHE_TTL);
        Ok(result)
    }

