    /// Run a skill.
    ///
    /// Skills may trigger long-running server-side operations (e.g. fleet
    /// deployments over SSH), so we use an extended timeout (default 120s,
    /// override with `MCP_SKILL_RUN_TIMEOUT_SECS`).
    pub async fn run_skill(
        &self,
        skill_id: Uuid,
        params: RunSkillParams,
    ) -> Result<serde_json::Value> {
        let timeout_secs = std::env::var("MCP_SKILL_RUN_TIMEOUT_SECS")
            .ok()
            .and_then(|v| v.trim().parse::<u64>().ok())
            .map(|v| v.clamp(10, 600))
            .unwrap_or(120);
        self.post_with_options(
            &format!("/skills/{}/run", skill_id),
            params,
            RequestOptions {
                timeout: Some(Duration::from_secs(timeout_secs)),
                retries: Some(1),
                ..Default::default()
            },
        )
        .await
    }

