    /// Get graph dependencies.
    pub async fn graph_dependencies(
        &self,
        params: GraphDependenciesParams,
    ) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let ws_id = params.workspace_id.or(config.default_workspace_id);
        let proj_id = params.project_id.or(config.default_project_id);
        drop(config);

        // Normalize target type
        let target_type = match params.target.target_type.to_lowercase().as_str() {
            "module" | "file" | "path" => "module",
            "type" => "type",
            "variable" | "var" | "const" => "variable",
            _ => "function",
        };

        // Build target based on type
        let target = if target_type == "module" {
            serde_json::json!({
                "type": target_type,
                "path": params.target.path.or(params.target.id),
            })
        } else {
            serde_json::json!({
                "type": target_type,
                "id": params.target.id,
            })
        };

        let body = serde_json::json!({
            "target": target,
            "workspace_id": ws_id,
            "project_id": proj_id,
            "max_depth": params.max_depth,
            "include_transitive": params.include_transitive,
        });

        self.post("/graph/dependencies", body).await
    }

    /// Get graph impact analysis.
    pub async fn graph_impact(&self, params: GraphImpactParams) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let ws_id = params.workspace_id.or(config.default_workspace_id);
        let proj_id = params.project_id.or(config.default_project_id);
        drop(config);

        let target_id = params.target_id.clone();
        let body = serde_json::json!({
            "change_type": params.change_type.unwrap_or_else(|| "modify_signature".to_string()),
            "target_id": target_id.clone(),
            "element_name": params.element_name,
            "workspace_id": ws_id,
            "project_id": proj_id,
            "target": {
                "id": target_id,
                "type": params.target_type,
            },
        });

        self.post("/graph/impact-analysis", body).await
    }

