    /// Get decisions from the knowledge graph.
    pub async fn graph_decisions(
        &self,
        workspace_id: Option<Uuid>,
        project_id: Option<Uuid>,
        category: Option<&str>,
        limit: Option<i64>,
    ) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let ws_id = workspace_id.or(config.default_workspace_id);
        let proj_id = project_id.or(config.default_project_id);
        drop(config);

        let now = chrono::Utc::now();
        let from = now - chrono::Duration::days(365 * 5);

        let body = serde_json::json!({
            "workspace_id": ws_id,
            "project_id": proj_id,
            "category": category.unwrap_or("general"),
            "from": from.to_rfc3339(),
            "to": now.to_rfc3339(),
            "limit": limit,
        });
        self.post("/graph/knowledge/decisions", body).await
    }

