    /// Find code that still references retired (superseded) knowledge.
    /// `refresh=true` recomputes findings on demand before returning them.
    pub async fn graph_code_drift(
        &self,
        node_id: Option<Uuid>,
        workspace_id: Option<Uuid>,
        project_id: Option<Uuid>,
        refresh: bool,
        limit: Option<i64>,
    ) -> Result<serde_json::Value> {
        let mut body = serde_json::Map::new();
        if let Some(n) = node_id {
            body.insert(
                "node_id".to_string(),
                serde_json::Value::String(n.to_string()),
            );
        }
        if let Some(w) = workspace_id {
            body.insert(
                "workspace_id".to_string(),
                serde_json::Value::String(w.to_string()),
            );
        }
        if let Some(p) = project_id {
            body.insert(
                "project_id".to_string(),
                serde_json::Value::String(p.to_string()),
            );
        }
        if refresh {
            body.insert("refresh".to_string(), serde_json::Value::Bool(true));
        }
        if let Some(l) = limit {
            body.insert("limit".to_string(), serde_json::Value::Number(l.into()));
        }
        self.post("/graph/code-drift", serde_json::Value::Object(body))
            .await
    }

