    /// Check integration status.
    pub async fn integration_status(
        &self,
        provider: &str,
        workspace_id: Option<Uuid>,
    ) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let ws_id = workspace_id.or(config.default_workspace_id);
        drop(config);

        let ws_id = ws_id.ok_or_else(|| {
            Error::Validation("workspace_id is required for integration status".to_string())
        })?;
        let cache_key = current_client_cache_identity()
            .map(|caller| Self::integration_status_cache_key(&caller, provider, ws_id));
        if let Some(cached) = self.cached_response(cache_key.as_ref()) {
            return Ok(cached);
        }

        let path = if provider.eq_ignore_ascii_case("all") {
            format!("/integrations/workspaces/{}/integrations/status", ws_id)
        } else {
            format!("/integrations/workspaces/{}/{}/status", ws_id, provider)
        };

        let result: serde_json::Value = self.get(&path).await?;
        self.cache_response(cache_key, result.clone(), ttl::INTEGRATION_STATUS);
        Ok(result)
    }

