    /// Get integration activity for a single provider.
    ///
    /// The backend exposes these as GET routes with query-string filters
    /// (`/integrations/workspaces/{id}/{provider}/activity`). Sending POST here
    /// caused HTTP 405; there is no aggregate "all" route (callers fan out).
    pub async fn integration_activity(
        &self,
        params: IntegrationActivityParams,
    ) -> Result<serde_json::Value> {
        let provider = params.provider.clone();
        let config = self.config.read().await;
        let ws_id = params.workspace_id.or(config.default_workspace_id);
        drop(config);
        let mut path = if let Some(id) = ws_id {
            format!("/integrations/workspaces/{}/{}/activity", id, provider)
        } else {
            format!("/integrations/{}/activity", provider)
        };
        let mut query: Vec<String> = Vec::new();
        if let Some(limit) = params.limit {
            query.push(format!("limit={}", limit));
        }
        if let Some(since) = params.since.as_deref() {
            query.push(format!("since={}", urlencoding::encode(since)));
        }
        if let Some(until) = params.until.as_deref() {
            query.push(format!("until={}", urlencoding::encode(until)));
        }
        if let Some(database_id) = params.database_id.as_deref() {
            query.push(format!("database_id={}", urlencoding::encode(database_id)));
        }
        if !query.is_empty() {
            path.push('?');
            path.push_str(&query.join("&"));
        }
        self.get(&path).await
    }

