    // =========================================================================
    // Taxonomy expansion entities (Phase 1-3 plan)
    //
    // Generic CRUD across the structured tables added by the memory-taxonomy
    // expansion: tickets, handoffs, backlog_views, incidents, releases,
    // experiments, goals (+ key_results), sprints, reviews, risks.
    //
    // The kinds map to URL fragments via `entity_kind_to_path`; bodies are
    // free-form JSON forwarded to the API verbatim, so adding a new column
    // on the API side doesn't require touching this layer.
    // =========================================================================

    /// List entities of `kind` with the given query params. Pass empty
    /// `params` for an unfiltered list. Defaults `workspace_id` /
    /// `project_id` from config when missing.
    pub async fn entity_list(
        &self,
        kind: &str,
        mut params: Vec<(String, String)>,
    ) -> Result<serde_json::Value> {
        let segment = entity_kind_to_path(kind).ok_or_else(|| {
            Error::Validation(format!(
                "Unknown entity kind: '{}'. Valid: {}",
                kind,
                VALID_ENTITY_KINDS.join(", ")
            ))
        })?;

        // Inject defaults for workspace_id / project_id if absent.
        let config = self.config.read().await;
        let has_ws = params.iter().any(|(k, _)| k == "workspace_id");
        let has_pj = params.iter().any(|(k, _)| k == "project_id");
        if !has_ws {
            if let Some(id) = config.default_workspace_id {
                params.push(("workspace_id".to_string(), id.to_string()));
            }
        }
        if !has_pj {
            if let Some(id) = config.default_project_id {
                params.push(("project_id".to_string(), id.to_string()));
            }
        }
        drop(config);

        let query: String = params
            .into_iter()
            .filter(|(_, v)| !v.is_empty())
            .map(|(k, v)| format!("{}={}", k, Self::url_encode(&v)))
            .collect::<Vec<_>>()
            .join("&");
        let path = if query.is_empty() {
            format!("/{}", segment)
        } else {
            format!("/{}?{}", segment, query)
        };
        self.get(&path).await
    }

    /// Get a single entity of `kind` by id.
    pub async fn entity_get(&self, kind: &str, id: Uuid) -> Result<serde_json::Value> {
        let segment = entity_kind_to_path(kind).ok_or_else(|| {
            Error::Validation(format!(
                "Unknown entity kind: '{}'. Valid: {}",
                kind,
                VALID_ENTITY_KINDS.join(", ")
            ))
        })?;
        self.get(&format!("/{}/{}", segment, id)).await
    }

    /// Create an entity of `kind` with the given body. Fills in
    /// `workspace_id` / `project_id` from config when missing.
    /// Special-cases `key_result` (nested under its parent goal).
    pub async fn entity_create(
        &self,
        kind: &str,
        mut body: serde_json::Value,
    ) -> Result<serde_json::Value> {
        if entity_kind_to_path(kind).is_none() {
            return Err(Error::Validation(format!(
                "Unknown entity kind: '{}'. Valid: {}",
                kind,
                VALID_ENTITY_KINDS.join(", ")
            )));
        }

        // Fill defaults from config.
        let config = self.config.read().await;
        if let Some(obj) = body.as_object_mut() {
            if !obj.contains_key("workspace_id") {
                if let Some(id) = config.default_workspace_id {
                    obj.insert("workspace_id".to_string(), serde_json::json!(id));
                }
            }
            if !obj.contains_key("project_id") {
                if let Some(id) = config.default_project_id {
                    obj.insert("project_id".to_string(), serde_json::json!(id));
                }
            }
        }
        drop(config);

        // Key-result creation is nested under the parent goal.
        if matches!(kind, "key_result" | "key-result" | "kr") {
            let goal_id = body
                .get("goal_id")
                .and_then(|v| v.as_str())
                .and_then(|s| Uuid::parse_str(s).ok())
                .ok_or_else(|| {
                    Error::Validation(
                        "goal_id (UUID) is required when creating a key_result".to_string(),
                    )
                })?;
            // The API doesn't accept goal_id in the body for nested create.
            if let Some(obj) = body.as_object_mut() {
                obj.remove("goal_id");
            }
            return self
                .post(&format!("/goals/{}/key-results", goal_id), body)
                .await;
        }

        let segment = entity_kind_to_path(kind).expect("validated above");
        self.post(&format!("/{}", segment), body).await
    }

    /// Update an entity of `kind` (PATCH).
    pub async fn entity_update(
        &self,
        kind: &str,
        id: Uuid,
        body: serde_json::Value,
    ) -> Result<serde_json::Value> {
        let segment = entity_kind_to_path(kind).ok_or_else(|| {
            Error::Validation(format!(
                "Unknown entity kind: '{}'. Valid: {}",
                kind,
                VALID_ENTITY_KINDS.join(", ")
            ))
        })?;
        self.patch(&format!("/{}/{}", segment, id), body).await
    }

    /// Delete (soft-delete) an entity of `kind`.
    pub async fn entity_delete(&self, kind: &str, id: Uuid) -> Result<serde_json::Value> {
        let segment = entity_kind_to_path(kind).ok_or_else(|| {
            Error::Validation(format!(
                "Unknown entity kind: '{}'. Valid: {}",
                kind,
                VALID_ENTITY_KINDS.join(", ")
            ))
        })?;
        self.delete(&format!("/{}/{}", segment, id)).await
    }

