    /// List reminders.
    pub async fn list_reminders(&self, params: ListRemindersParams) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let ws_id = params.workspace_id.or(config.default_workspace_id);
        let proj_id = params.project_id.or(config.default_project_id);
        drop(config);

        let mut path = "/reminders".to_string();
        let mut query_params = Vec::new();
        if let Some(id) = ws_id {
            query_params.push(format!("workspace_id={}", id));
        }
        if let Some(id) = proj_id {
            query_params.push(format!("project_id={}", id));
        }
        if let Some(s) = &params.status {
            query_params.push(format!("status={}", s));
        }
        if let Some(ctx) = &params.context {
            query_params.push(format!("context={}", Self::url_encode(ctx)));
        }
        if let Some(l) = params.limit {
            query_params.push(format!("limit={}", l));
        }
        if !query_params.is_empty() {
            path.push_str(&format!("?{}", query_params.join("&")));
        }
        self.get(&path).await
    }

