    pub async fn feed_changes(
        &self,
        workspace_id: Option<Uuid>,
        cursor: Option<i64>,
        limit: Option<u16>,
    ) -> Result<serde_json::Value> {
        let path = build_feed_changes_path(workspace_id, cursor, limit);
        self.get(&path)
            .await
            .map_err(|error| map_feed_error(error, "Feed changes"))
    }

    // =========================================================================
    // Media
    // =========================================================================

    /// Index a media file. For local files, initiates upload; for external URLs, indexes directly.
    pub async fn media_index(&self, params: MediaIndexParams) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let ws_id = params
            .workspace_id
            .or(config.default_workspace_id)
            .ok_or_else(|| {
                Error::Validation("workspace_id is required for media operations".to_string())
            })?;
        drop(config);

        if let Some(file_path) = &params.file_path {
            // Local file: use upload flow
            let path = std::path::Path::new(file_path);
            let filename = path
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or("unknown")
                .to_string();

            let metadata = std::fs::metadata(file_path)?;
            // P0 ingestion-containment backstop: only ever upload a regular
            // file, and never one larger than the media cap (bounds exfil and
            // the in-memory read below). The mcp-tools media handler performs the
            // richer containment/secret checks; this guards direct callers too.
            if !metadata.is_file() {
                return Err(Error::Validation(format!(
                    "media upload requires a regular file, not a directory or special file: {}",
                    file_path
                )));
            }
            let size_bytes = metadata.len();
            if size_bytes > MEDIA_INDEX_MAX_BYTES {
                return Err(Error::Validation(format!(
                    "media upload refused: '{}' is {} bytes, exceeding the {}-byte single-asset limit",
                    file_path, size_bytes, MEDIA_INDEX_MAX_BYTES
                )));
            }
            // Never upload a secret/credential file. The mcp-tools media handler
            // performs richer containment checks; this is defense-in-depth for any
            // direct caller of media_index.
            if Self::should_skip_file(&filename, true) {
                return Err(Error::Validation(format!(
                    "media upload refused: '{}' matches the blocked-file (secret/credential) filter",
                    file_path
                )));
            }

            // Detect content type from extension
            let content_type = params.content_type.clone().unwrap_or_else(|| {
                let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
                match ext.to_lowercase().as_str() {
                    "mp4" | "mov" | "avi" | "mkv" | "webm" => "video",
                    "mp3" | "wav" | "ogg" | "m4a" | "flac" => "audio",
                    "jpg" | "jpeg" | "png" | "gif" | "webp" | "bmp" => "image",
                    _ => "document",
                }
                .to_string()
            });

            // Step 1: Initialize upload
            let init_body = serde_json::json!({
                "filename": filename,
                "size_bytes": size_bytes,
                "content_type": content_type.to_lowercase(),
                "tags": params.tags.unwrap_or_default(),
                "project_id": params.project_id,
            });
            let init_result: serde_json::Value = self
                .post(
                    &format!("/workspaces/{}/content/uploads/init", ws_id),
                    &init_body,
                )
                .await?;

            let content_id = init_result
                .get("content_id")
                .and_then(|v| v.as_str())
                .ok_or_else(|| Error::Tool("No content_id in upload init response".to_string()))?;
            let upload_url = init_result
                .get("upload_url")
                .and_then(|v| v.as_str())
                .ok_or_else(|| Error::Tool("No upload_url in upload init response".to_string()))?;
            let upload_headers = init_result
                .get("headers")
                .and_then(|v| v.as_object())
                .cloned()
                .unwrap_or_default();

            // Step 2: Upload file to presigned URL
            let file_content = std::fs::read(file_path)?;

            let upload_client = reqwest::Client::new();
            let mut upload_request = upload_client.put(upload_url);
            for (name, value) in upload_headers {
                if let Some(value) = value.as_str() {
                    upload_request = upload_request.header(name.as_str(), value);
                }
            }
            let upload_response = upload_request
                .body(file_content)
                .send()
                .await
                .map_err(|e| Error::Network(e.to_string()))?;

            if !upload_response.status().is_success() {
                return Err(Error::http(
                    upload_response.status().as_u16(),
                    format!("Upload failed: {}", upload_response.status()),
                ));
            }

            // Step 3: Complete upload
            let complete_result: serde_json::Value = self
                .post(
                    &format!(
                        "/workspaces/{}/content/{}/complete-upload",
                        ws_id, content_id
                    ),
                    &serde_json::json!({}),
                )
                .await?;

            Ok(complete_result)
        } else if let Some(external_url) = &params.external_url {
            // External URL: index directly (API handles fetching)
            let filename = external_media_filename(external_url, params.content_type.as_deref());
            let body = serde_json::json!({
                "external_url": external_url,
                "filename": filename,
                "content_type": params.content_type,
                "tags": params.tags.unwrap_or_default(),
                "project_id": params.project_id,
            });
            self.post(&format!("/workspaces/{}/content/external", ws_id), &body)
                .await
        } else {
            Err(Error::Validation(
                "Either file_path or external_url is required".to_string(),
            ))
        }
    }

