    /// Get a specific clip/segment from indexed content.
    pub async fn media_get_clip(&self, params: MediaGetClipParams) -> Result<serde_json::Value> {
        let config = self.config.read().await;
        let ws_id = params
            .workspace_id
            .or(config.default_workspace_id)
            .ok_or_else(|| {
                Error::Validation("workspace_id is required for media operations".to_string())
            })?;
        drop(config);

        let mut query_params = Vec::new();
        // Parse time strings to seconds
        if let Some(start_secs) = Self::parse_time_to_seconds(&params.start) {
            query_params.push(format!("start_time={}", start_secs));
        }
        if let Some(end_secs) = Self::parse_time_to_seconds(&params.end) {
            query_params.push(format!("end_time={}", end_secs));
        }
        if let Some(format) = &params.output_format {
            query_params.push(format!("format={}", format));
        }
        if let Some(fps) = params.fps {
            query_params.push(format!("fps={}", fps));
        }

        let suffix = if query_params.is_empty() {
            "".to_string()
        } else {
            format!("?{}", query_params.join("&"))
        };
        self.get(&format!(
            "/workspaces/{}/content/{}/clip{}",
            ws_id, params.content_id, suffix
        ))
        .await
    }

    /// Parse time string like "1:34" or "94s" to seconds.
    fn parse_time_to_seconds(time_str: &str) -> Option<f64> {
        let s = time_str.trim();
        if s.ends_with('s') {
            s.trim_end_matches('s').parse().ok()
        } else if s.contains(':') {
            let parts: Vec<&str> = s.split(':').collect();
            match parts.len() {
                2 => {
                    let mins: f64 = parts[0].parse().ok()?;
                    let secs: f64 = parts[1].parse().ok()?;
                    Some(mins * 60.0 + secs)
                }
                3 => {
                    let hours: f64 = parts[0].parse().ok()?;
                    let mins: f64 = parts[1].parse().ok()?;
                    let secs: f64 = parts[2].parse().ok()?;
                    Some(hours * 3600.0 + mins * 60.0 + secs)
                }
                _ => None,
            }
        } else {
            s.parse().ok()
        }
    }

