/// Request options.
#[derive(Debug, Clone, Default)]
pub struct RequestOptions {
    pub auth_override: Option<AuthOverride>,
    pub workspace_id: Option<Uuid>,
    pub timeout: Option<Duration>,
    pub retries: Option<u32>,
    pub extra_headers: Option<Vec<(String, String)>>,
}

fn request_options_has_header(options: &RequestOptions, name: &str) -> bool {
    options.extra_headers.as_ref().is_some_and(|headers| {
        headers
            .iter()
            .any(|(candidate, _)| candidate.eq_ignore_ascii_case(name))
    })
}

#[cfg(test)]
mod request_options_header_tests {
    use super::{request_options_has_header, RequestOptions};

    #[test]
    fn explicit_header_detection_is_case_insensitive() {
        let options = RequestOptions {
            extra_headers: Some(vec![(
                "x-contextstream-installation-id".to_string(),
                "explicit".to_string(),
            )]),
            ..Default::default()
        };

        assert!(request_options_has_header(
            &options,
            "X-ContextStream-Installation-Id"
        ));
        assert!(!request_options_has_header(
            &options,
            "X-ContextStream-Client"
        ));
    }
}

/// Graph tier.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum GraphTier {
    None,
    Lite,
    Full,
}

impl GraphTier {
    // Inherent from_str (infallible, returns Self) predates and differs from the
    // fallible std::str::FromStr; keep the convenient inherent API.
    #[allow(clippy::should_implement_trait)]
    pub fn from_str(s: &str) -> Self {
        let lower = s.to_lowercase();
        if lower.contains("full") || lower.contains("elite") || lower.contains("team") {
            Self::Full
        } else if lower.contains("lite") || lower.contains("light") || lower.contains("basic") {
            Self::Lite
        } else {
            Self::None
        }
    }
}

