/// Result of resolving the capsule scope on the MCP side, before the
/// request goes to the backend. Returned by
/// `CreateCapsuleParams::resolve_locally` so callers (today only
/// `create_capsule`) can stitch this into the response's `resolved_scope`
/// when the backend can't.
#[derive(Debug, Clone, Default)]
pub struct LocalScopeResolution {
    pub method: &'static str,
    pub confidence: f32,
    pub workspace_id: Option<Uuid>,
    pub project_id: Option<Uuid>,
    pub resolved_from: Option<String>,
}

impl CreateCapsuleParams {
    /// Resolve `folder_path` → `project_id` locally (no network) when the
    /// caller did not pass an explicit `project_id`. Mutates `self` and
    /// returns the resolution metadata so the caller can echo it back to
    /// the agent as part of the capsule response.
    fn resolve_locally(&mut self, config: &Config) -> LocalScopeResolution {
        let workspace_default = self.workspace_id.or(config.default_workspace_id);
        let mut resolution = LocalScopeResolution {
            method: "workspace",
            confidence: 0.0,
            workspace_id: workspace_default,
            project_id: None,
            resolved_from: None,
        };

        if matches!(self.scope.as_deref(), Some("session")) {
            resolution.method = if self.transcript_id.is_some() {
                "transcript_id"
            } else {
                "session_id"
            };
            resolution.confidence = if self.transcript_id.is_some() {
                1.0
            } else {
                0.9
            };
            resolution.resolved_from = self
                .transcript_id
                .map(|id| id.to_string())
                .or_else(|| self.session_id.clone());
            return resolution;
        }

        if let Some(pid) = self.project_id.or(config.default_project_id) {
            resolution.method = "explicit";
            resolution.confidence = 1.0;
            resolution.project_id = Some(pid);
            return resolution;
        }

        if let Some(folder) = self.folder_path.as_deref() {
            if let Some(pid) = ContextStreamClient::tracked_project_id_for_folder(folder) {
                self.project_id = Some(pid);
                resolution.method = "folder_path";
                // The local index uses longest-prefix matching, so a hit
                // is high-confidence even when the user passed a
                // subdirectory of the indexed root.
                resolution.confidence = 0.95;
                resolution.project_id = Some(pid);
                resolution.resolved_from = Some(folder.to_string());
                return resolution;
            }
        }

        if let Some(name) = self.project_name.as_deref() {
            // Backend resolution; MCP-side cannot fill project_id here.
            resolution.method = "project_name";
            resolution.confidence = 0.0; // backend will overwrite on success
            resolution.resolved_from = Some(name.to_string());
            return resolution;
        }

        resolution
    }

    fn with_defaults(self, config: &Config) -> serde_json::Value {
        let scope = self.scope.unwrap_or_else(|| {
            if self.project_id.or(config.default_project_id).is_some() {
                "project".to_string()
            } else {
                "workspace".to_string()
            }
        });
        let is_session = scope == "session";
        let mut body = serde_json::Map::new();
        body.insert("scope".to_string(), serde_json::json!(scope));

        if let Some(workspace_id) = self.workspace_id.or(config.default_workspace_id) {
            body.insert("workspace_id".to_string(), serde_json::json!(workspace_id));
        }
        if let Some(project_id) = self.project_id.or(config.default_project_id) {
            body.insert("project_id".to_string(), serde_json::json!(project_id));
        }
        if let Some(session_id) = self.session_id {
            body.insert("session_id".to_string(), serde_json::json!(session_id));
        }
        if let Some(transcript_id) = self.transcript_id {
            body.insert(
                "transcript_id".to_string(),
                serde_json::json!(transcript_id),
            );
        }
        if let Some(folder_path) = self.folder_path {
            // Echoed so server-side audit / backend slice 2 resolution can
            // see what the caller used. The backend ignores unknown
            // fields today.
            body.insert("folder_path".to_string(), serde_json::json!(folder_path));
        }
        if let Some(project_name) = self.project_name {
            body.insert("project_name".to_string(), serde_json::json!(project_name));
        }
        if let Some(pin_items) = self.pin_items {
            if !pin_items.is_empty() {
                body.insert("pin_items".to_string(), serde_json::json!(pin_items));
            }
        }
        if let Some(notes) = self.notes {
            if !notes.trim().is_empty() {
                body.insert("notes".to_string(), serde_json::json!(notes));
            }
        }
        if let Some(external_refs) = self.external_refs {
            if !external_refs.is_empty() {
                body.insert(
                    "external_refs".to_string(),
                    serde_json::json!(external_refs),
                );
            }
        }
        if let Some(name) = self.name {
            body.insert("name".to_string(), serde_json::json!(name));
        }
        if let Some(purpose) = self.purpose {
            body.insert("purpose".to_string(), serde_json::json!(purpose));
        } else if is_session {
            body.insert("purpose".to_string(), serde_json::json!("handoff"));
        }
        if let Some(mode) = self.mode {
            body.insert("mode".to_string(), serde_json::json!(mode));
        } else if is_session {
            body.insert("mode".to_string(), serde_json::json!("snapshot"));
        }
        if let Some(sections) = self.sections {
            body.insert("sections".to_string(), serde_json::json!(sections));
        }
        if let Some(audience) = self.audience {
            body.insert("audience".to_string(), serde_json::json!(audience));
        }
        if let Some(include_personal) = self.include_personal {
            body.insert(
                "include_personal".to_string(),
                serde_json::json!(include_personal),
            );
        } else if is_session {
            body.insert("include_personal".to_string(), serde_json::json!(true));
        }
        if let Some(include_code) = self.include_code {
            body.insert("include_code".to_string(), serde_json::json!(include_code));
        } else if is_session {
            body.insert("include_code".to_string(), serde_json::json!("lazy"));
        }
        if let Some(redaction_level) = self.redaction_level {
            body.insert(
                "redaction_level".to_string(),
                serde_json::json!(redaction_level),
            );
        } else if is_session {
            body.insert("redaction_level".to_string(), serde_json::json!("standard"));
        }
        if let Some(permissions) = self.permissions {
            body.insert("permissions".to_string(), serde_json::json!(permissions));
        }
        if let Some(max_inline_tokens) = self.max_inline_tokens {
            body.insert(
                "max_inline_tokens".to_string(),
                serde_json::json!(max_inline_tokens),
            );
        }
        if let Some(refresh_if_stale) = self.refresh_if_stale {
            body.insert(
                "refresh_if_stale".to_string(),
                serde_json::json!(refresh_if_stale),
            );
        }

        serde_json::Value::Object(body)
    }
}

