/// Resolve a `brain_*` / `capsule_*` token or extract one from a `/c/` or API URL.
pub fn resolve_capsule_share_token_str(value: &str) -> Result<String> {
    extract_capsule_share_token(value.trim()).ok_or_else(|| {
        Error::Validation(
            "Could not resolve a capsule share token; pass share_token or a URL containing /c/, brain_, capsule_, or /api/v1/capsules/shares/"
                .to_string(),
        )
    })
}

fn extract_capsule_share_token(value: &str) -> Option<String> {
    let trimmed = value.trim();
    if trimmed.starts_with("brain_") || trimmed.starts_with("capsule_") {
        return Some(
            trimmed
                .trim_end_matches(".md")
                .trim_end_matches(".txt")
                .to_string(),
        );
    }

    let patterns = ["/api/v1/brain/shares/", "/api/v1/capsules/shares/", "/c/"];
    for pattern in patterns {
        if let Some(index) = trimmed.find(pattern) {
            let token = &trimmed[index + pattern.len()..];
            let token = token
                .split(['/', '?', '#'])
                .next()
                .unwrap_or_default()
                .trim_end_matches(".md")
                .trim_end_matches(".txt");
            if !token.is_empty() {
                return Some(token.to_string());
            }
        }
    }

    None
}

fn extract_capsule_id(value: &str) -> Option<String> {
    let trimmed = value.trim();
    if trimmed.starts_with("cap_") {
        return Some(trimmed.to_string());
    }
    if let Some(index) = trimmed.find("/api/v1/capsules/") {
        let suffix = &trimmed[index + "/api/v1/capsules/".len()..];
        let capsule_id = suffix.split(['/', '?', '#']).next().unwrap_or_default();
        if capsule_id.starts_with("cap_") {
            return Some(capsule_id.to_string());
        }
    }
    None
}

