/// Session init parameters.
#[derive(Debug, Clone, Default, Serialize)]
pub struct SessionInitParams {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub workspace_id: Option<Uuid>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub project_id: Option<Uuid>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub folder_path: Option<String>,
    /// Credential-free canonical Git remote used by the API to resolve one
    /// repository across machines and worktrees before basename heuristics.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub repository_url: Option<String>,
    /// Durable session identity (MCP session id on hosted transports); the
    /// backend persists the init-resolved scope under it so later scope-less
    /// calls in the same session can be rehydrated across gateway pods.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub session_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub context_hint: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub include_recent_memory: Option<bool>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub include_decisions: Option<bool>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub allow_no_workspace: Option<bool>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub skip_project_creation: Option<bool>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub client_name: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tool_surface_profile: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub auto_index: Option<bool>,
    /// How this client resolved the ids it is sending: `explicit`
    /// (caller-passed), `local_mapping` (validated .contextstream folder
    /// mapping), `inherited` (header-pinned gateway scope), or `unresolved`.
    /// The backend only learns folder→project bindings from user-authored
    /// resolutions, so this must never overstate confidence.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub scope_provenance: Option<String>,
}

impl SessionInitParams {
    #[allow(dead_code)]
    fn with_defaults(self, config: &Config) -> serde_json::Value {
        let (workspace_id, project_id) =
            scope_ids_with_defaults(self.workspace_id, self.project_id, config);
        let checkout_scope = self
            .folder_path
            .as_deref()
            .and_then(ContextStreamClient::checkout_routing_scope);
        let mut json = serde_json::json!({
            "workspace_id": workspace_id,
            "project_id": project_id,
            "folder_path": self.folder_path,
            "session_id": self.session_id,
            "context_hint": self.context_hint,
        });
        if let Some(repository_url) = self
            .repository_url
            .as_deref()
            .and_then(credential_free_canonical_repository_url)
        {
            json["repository_url"] = serde_json::Value::String(repository_url.to_string());
        }
        if let Some(scope) = checkout_scope {
            json["installation_id"] = serde_json::json!(scope.installation_id);
            json["checkout_locator"] = serde_json::json!(scope.checkout_locator);
        }
        if let Some(v) = self.include_recent_memory {
            json["include_recent_memory"] = serde_json::Value::Bool(v);
        }
        if let Some(v) = self.include_decisions {
            json["include_decisions"] = serde_json::Value::Bool(v);
        }
        if let Some(v) = self.allow_no_workspace {
            json["allow_no_workspace"] = serde_json::Value::Bool(v);
        }
        if let Some(v) = self.skip_project_creation {
            json["skip_project_creation"] = serde_json::Value::Bool(v);
        }
        if let Some(v) = self.client_name {
            json["client_name"] = serde_json::Value::String(v);
        }
        if let Some(v) = self
            .tool_surface_profile
            .or_else(|| Some(config.tool_surface_profile.as_str().to_string()))
        {
            json["tool_surface_profile"] = serde_json::Value::String(v);
        }
        if let Some(v) = self.auto_index {
            json["auto_index"] = serde_json::Value::Bool(v);
        }
        if let Some(v) = self.scope_provenance {
            json["scope_provenance"] = serde_json::Value::String(v);
        }
        if crate::activation::activation_enabled() && !config.is_http_transport {
            let runtime = crate::activation::runtime_metadata();
            json["runtime"] = serde_json::Value::String("contextstream_mcp".to_string());
            if json.get("installation_id").is_none() {
                json["installation_id"] =
                    serde_json::Value::String(runtime.installation_id.to_string());
            }
            json["client_version"] = serde_json::Value::String(runtime.client_version);
            json["os_family"] = serde_json::Value::String(runtime.os_family);
            json["os_version"] = serde_json::Value::String(runtime.os_version);
            json["architecture"] = serde_json::Value::String(runtime.architecture);
            json["onboarding_version"] = serde_json::Value::String(runtime.onboarding_version);
            json["connection_transport"] = serde_json::Value::String(
                if config.is_http_transport {
                    "http"
                } else {
                    "stdio"
                }
                .to_string(),
            );
            if !runtime.configured_clients.is_empty() {
                json["configured_clients"] = serde_json::json!(runtime.configured_clients);
            }
        }
        strip_nulls(json)
    }
}

