/// Parameters for capturing a local VCS event observed by managed git hooks.
///
/// `event_type` is one of `commit.local`, `push.local`, `branch.checkout`,
/// `merge.local`. All optional fields are stripped from the request body when
/// `None`, so handlers only send what they could collect within their budget.
#[derive(Debug, Clone, Default)]
pub struct CaptureVcsLocalEventParams {
    pub workspace_id: Option<Uuid>,
    pub project_id: Option<Uuid>,
    /// `commit.local` | `push.local` | `branch.checkout` | `merge.local`.
    pub event_type: String,
    /// Credential-free canonical repository URL. Raw configured remotes are
    /// rejected at the client boundary.
    pub remote_url: Option<String>,
    /// Opaque `checkout-v1:<uuid>` identifier. Despite the legacy wire-field
    /// name, absolute or relative filesystem paths are rejected.
    pub repo_path: Option<String>,
    pub sha: Option<String>,
    pub message: Option<String>,
    /// Deprecated compatibility inputs. The open-source client never sends
    /// commit-author identity to ContextStream.
    pub author_name: Option<String>,
    pub author_email: Option<String>,
    pub branch: Option<String>,
    pub additions: Option<i64>,
    pub deletions: Option<i64>,
    pub files_changed: Option<i64>,
    pub pushed_refs: Option<Vec<String>>,
    /// RFC3339 author/commit time when available.
    pub committed_at: Option<String>,
    pub session_id: Option<String>,
    pub agent: Option<String>,
}

const VCS_MESSAGE_MAX_CHARS: usize = 256;
const VCS_REF_MAX_CHARS: usize = 160;
const VCS_SESSION_MAX_CHARS: usize = 160;
const VCS_AGENT_MAX_CHARS: usize = 64;
const VCS_PUSHED_REFS_MAX: usize = 32;

fn vcs_local_event_body(
    params: CaptureVcsLocalEventParams,
    project_id: Option<Uuid>,
) -> Result<serde_json::Value> {
    let event_type = match params.event_type.as_str() {
        "commit.local" | "push.local" | "branch.checkout" | "merge.local" => params.event_type,
        _ => {
            return Err(Error::Validation(
                "unsupported local VCS event type".to_string(),
            ))
        }
    };

    let repo_path = params.repo_path.and_then(sanitize_checkout_id);
    let remote_url = params.remote_url.and_then(sanitize_repository_url);
    let sha = params.sha.and_then(sanitize_sha);
    let message = params
        .message
        .and_then(|value| sanitize_free_text(value, VCS_MESSAGE_MAX_CHARS));
    let branch = params
        .branch
        .and_then(|value| sanitize_identifier(value, VCS_REF_MAX_CHARS));
    let pushed_refs = params.pushed_refs.and_then(|refs| {
        let refs = refs
            .into_iter()
            .take(VCS_PUSHED_REFS_MAX)
            .filter_map(|value| sanitize_identifier(value, VCS_REF_MAX_CHARS))
            .collect::<Vec<_>>();
        (!refs.is_empty()).then_some(refs)
    });
    let committed_at = params.committed_at.and_then(|value| {
        chrono::DateTime::parse_from_rfc3339(value.trim())
            .ok()
            .map(|time| time.to_rfc3339())
    });
    let session_id = params
        .session_id
        .and_then(|value| sanitize_identifier(value, VCS_SESSION_MAX_CHARS));
    let agent = params
        .agent
        .and_then(|value| sanitize_identifier(value, VCS_AGENT_MAX_CHARS));

    Ok(strip_nulls(serde_json::json!({
        "project_id": project_id,
        "remote_url": remote_url,
        "repo_path": repo_path,
        "event_type": event_type,
        "sha": sha,
        "message": message,
        "branch": branch,
        "additions": params.additions.filter(|value| *value >= 0),
        "deletions": params.deletions.filter(|value| *value >= 0),
        "files_changed": params.files_changed.filter(|value| *value >= 0),
        "pushed_refs": pushed_refs,
        "committed_at": committed_at,
        "session_id": session_id,
        "agent": agent,
    })))
}

fn sanitize_checkout_id(value: String) -> Option<String> {
    let value = value.trim();
    let id = value.strip_prefix("checkout-v1:")?;
    let id = Uuid::parse_str(id).ok()?;
    Some(format!("checkout-v1:{id}"))
}

fn sanitize_repository_url(value: String) -> Option<String> {
    let url = reqwest::Url::parse(value.trim()).ok()?;
    if !matches!(url.scheme(), "http" | "https") {
        return None;
    }
    let host = url.host_str()?.to_ascii_lowercase();
    let namespace = url.path().trim_matches('/').trim_end_matches(".git");
    if namespace.is_empty()
        || namespace
            .split('/')
            .any(|segment| segment.is_empty() || matches!(segment, "." | ".."))
    {
        return None;
    }
    let authority = match url.port() {
        Some(port) => format!("{host}:{port}"),
        None => host,
    };
    Some(format!("https://{authority}/{namespace}.git"))
}

fn sanitize_sha(value: String) -> Option<String> {
    let value = value.trim();
    ((7..=64).contains(&value.len()) && value.bytes().all(|byte| byte.is_ascii_hexdigit()))
        .then(|| value.to_ascii_lowercase())
}

fn sanitize_identifier(value: String, max_chars: usize) -> Option<String> {
    let sanitized = value
        .trim()
        .chars()
        .filter(|character| !character.is_control())
        .take(max_chars)
        .collect::<String>();
    (!sanitized.is_empty()).then_some(sanitized)
}

fn sanitize_free_text(value: String, max_chars: usize) -> Option<String> {
    let subject = value.lines().next().unwrap_or_default().trim();
    let mut output = Vec::new();
    let mut redact_next = false;
    for raw_token in subject.split_whitespace() {
        if output.join(" ").chars().count() >= max_chars {
            break;
        }
        if redact_next {
            output.push("[redacted-secret]".to_string());
            redact_next = false;
            continue;
        }
        let token = raw_token.trim_matches(|character: char| {
            matches!(character, ',' | ';' | '(' | ')' | '[' | ']' | '{' | '}')
        });
        let lower = token.to_ascii_lowercase();
        if lower == "bearer" || lower == "authorization" {
            output.push("[redacted-secret]".to_string());
            redact_next = true;
        } else if lower.contains("://") {
            output.push("[redacted-url]".to_string());
        } else if token.contains('@') {
            output.push("[redacted-email]".to_string());
        } else if token.starts_with('/')
            || token.starts_with('~')
            || token.starts_with("\\\\")
            || (token.len() > 2
                && token.as_bytes()[1] == b':'
                && matches!(token.as_bytes()[2], b'\\' | b'/'))
        {
            output.push("[redacted-path]".to_string());
        } else if ["api_key", "apikey", "token", "password", "passwd", "secret"]
            .iter()
            .any(|prefix| {
                lower.starts_with(prefix)
                    && lower
                        .as_bytes()
                        .get(prefix.len())
                        .is_some_and(|separator| matches!(separator, b'=' | b':'))
            })
        {
            output.push("[redacted-secret]".to_string());
        } else {
            output.push(token.to_string());
        }
    }

    let sanitized = output.join(" ");
    let truncated = sanitized.chars().take(max_chars).collect::<String>();
    (!truncated.is_empty()).then_some(truncated)
}

