/// Create skill parameters.
#[derive(Debug, Clone, Default, Serialize)]
pub struct CreateSkillParams {
    pub name: String,
    pub title: String,
    pub instruction_body: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub trigger_patterns: Option<Vec<String>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub trigger_regex: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub categories: Option<Vec<String>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub actions: Option<serde_json::Value>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub capability_manifest: Option<serde_json::Value>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub scope: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub is_personal: Option<bool>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub priority: Option<i32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub status: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub source_tool: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub source_file: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub workspace_id: Option<Uuid>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub project_id: Option<Uuid>,
}

impl CreateSkillParams {
    fn with_defaults(self, config: &Config) -> serde_json::Value {
        // Skills saved through the MCP default to "active" status unless the
        // caller explicitly requests "draft" (or any other status). This mirrors
        // the Rust backend's `SkillStatus::default()` which returns `Active`.
        // Without this, the API endpoint falls back to "draft" when no status is
        // sent, forcing users to manually activate skills in the dashboard.
        let status = self.status.or_else(|| Some("active".to_string()));
        strip_nulls(serde_json::json!({
            "name": self.name,
            "title": self.title,
            "instruction_body": self.instruction_body,
            "description": self.description,
            "trigger_patterns": self.trigger_patterns,
            "trigger_regex": self.trigger_regex,
            "categories": self.categories,
            "actions": self.actions,
            "capability_manifest": self.capability_manifest,
            "scope": self.scope,
            "is_personal": self.is_personal,
            "priority": self.priority,
            "status": status,
            "source_tool": self.source_tool,
            "source_file": self.source_file,
            "workspace_id": self.workspace_id.or(config.default_workspace_id),
            "project_id": self.project_id.or(config.default_project_id),
        }))
    }
}

