#[derive(Debug, Clone)]
pub enum IngestProgressEvent {
    /// Periodic update during the local hash/mtime scan. Fires before
    /// any network calls happen — for large repos this loop is the
    /// long silent prelude that left users staring at a 0% bar for
    /// 30+ seconds. Wizards should render a real progress bar
    /// (`hashed_files / total_files`) on receipt of this variant
    /// rather than waiting for `ScanComplete`.
    ScanProgress {
        hashed_files: usize,
        total_files: usize,
    },
    ScanComplete {
        total_files: usize,
        changed_files: usize,
        skipped_files: usize,
    },
    UploadProgress {
        uploaded_files: i64,
        total_changed_files: i64,
        batch_files: i64,
    },
    WaitingForServer {
        job_count: i64,
        uploaded_files: i64,
    },
    ServerProgress {
        files_processed: i64,
        files_total: i64,
        completed_jobs: i64,
        total_jobs: i64,
        phases: Vec<String>,
    },
    Complete {
        files_uploaded: i64,
        files_indexed: i64,
        total_files: usize,
        skipped_files: usize,
    },
}

