/// Whether a filesystem-path ingest may be delegated to the API server's
/// `ingest-from-path` endpoint. That endpoint reads the path from the API
/// host's own disk, so delegation can only work when the API shares this
/// machine's filesystem: a loopback API URL (self-hosted/dev), or an explicit
/// `CONTEXTSTREAM_ALLOW_API_PATH_INGEST=1` opt-in for shared-volume setups.
/// Hosted APIs must never be asked to read local paths — they 400 with
/// "Invalid path" for every workstation folder.
fn path_ingest_delegation_allowed(api_url: &str, env_opt_in: Option<&str>) -> bool {
    if matches!(
        env_opt_in.map(str::trim),
        Some("1") | Some("true") | Some("TRUE") | Some("yes")
    ) {
        return true;
    }
    api_url_host_is_loopback(api_url)
}

/// Lightweight authority parse (no extra deps): `scheme://user@host:port/...`.
fn api_url_host_is_loopback(api_url: &str) -> bool {
    let rest = api_url
        .split_once("://")
        .map(|(_, rest)| rest)
        .unwrap_or(api_url);
    let authority = rest.split(['/', '?', '#']).next().unwrap_or("");
    let host_port = authority
        .rsplit_once('@')
        .map(|(_, host)| host)
        .unwrap_or(authority);
    let host = if let Some(bracketed) = host_port.strip_prefix('[') {
        bracketed.split(']').next().unwrap_or("")
    } else {
        host_port.split(':').next().unwrap_or(host_port)
    };
    let host = host.to_ascii_lowercase();
    if host == "localhost" {
        return true;
    }
    host.parse::<std::net::IpAddr>()
        .map(|ip| ip.is_loopback())
        .unwrap_or(false)
}

#[cfg(test)]
mod path_ingest_gate_tests {
    use super::{api_url_host_is_loopback, path_ingest_delegation_allowed};

    #[test]
    fn hosted_api_urls_never_allow_path_delegation() {
        for url in [
            "https://api.contextstream.io",
            "https://api.contextstream.io/v1",
            "https://user:pass@api.contextstream.io:443/v1",
            "http://10.0.0.5:8080",
            "http://192.168.1.20/api",
            "not a url",
            "",
        ] {
            assert!(
                !path_ingest_delegation_allowed(url, None),
                "expected delegation to be blocked for {url:?}"
            );
        }
    }

    #[test]
    fn loopback_api_urls_allow_path_delegation() {
        for url in [
            "http://localhost:3000",
            "http://localhost",
            "https://LOCALHOST:8443/api",
            "http://127.0.0.1:8080/v1",
            "http://127.0.0.53",
            "http://[::1]:3000",
            "http://user@localhost:9999/x?q=1",
        ] {
            assert!(
                path_ingest_delegation_allowed(url, None),
                "expected delegation to be allowed for {url:?}"
            );
            assert!(api_url_host_is_loopback(url));
        }
    }

    #[test]
    fn env_opt_in_overrides_remote_api_host() {
        assert!(path_ingest_delegation_allowed(
            "https://api.contextstream.io",
            Some("1")
        ));
        assert!(path_ingest_delegation_allowed(
            "https://api.contextstream.io",
            Some("true")
        ));
        assert!(!path_ingest_delegation_allowed(
            "https://api.contextstream.io",
            Some("0")
        ));
        assert!(!path_ingest_delegation_allowed(
            "https://api.contextstream.io",
            Some("")
        ));
    }
}

