    fn env_test_mutex() -> &'static Mutex<()> {
        // Delegate to the crate-wide env lock so HOME mutations here are
        // serialized against env-reading tests in other modules (ingest_guard).
        crate::test_env_lock()
    }

    async fn client_with_release_response(
        status: &str,
        body: &str,
    ) -> (ContextStreamClient, tokio::task::JoinHandle<String>) {
        use tokio::io::{AsyncReadExt, AsyncWriteExt};

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind release metadata test listener");
        let addr = listener
            .local_addr()
            .expect("release metadata listener addr");
        let response = format!(
            "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );

        let server = tokio::spawn(async move {
            let (mut socket, _) = listener.accept().await.expect("accept release request");
            let mut buf = vec![0u8; 4096];
            let n = socket.read(&mut buf).await.expect("read release request");
            let request = String::from_utf8_lossy(&buf[..n]).to_string();
            socket
                .write_all(response.as_bytes())
                .await
                .expect("write release response");
            request
        });

        let mut config = Config::default();
        config.api_url = format!("http://{addr}");
        config.api_key = Some("test-key".to_string());
        (ContextStreamClient::new(config), server)
    }

    async fn client_with_http_sequence(
        responses: Vec<(&'static str, String)>,
    ) -> (ContextStreamClient, tokio::task::JoinHandle<Vec<String>>) {
        use tokio::io::{AsyncReadExt, AsyncWriteExt};

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind HTTP sequence listener");
        let addr = listener.local_addr().expect("HTTP sequence listener addr");
        let server = tokio::spawn(async move {
            let mut requests = Vec::with_capacity(responses.len());
            for (status, body) in responses {
                let (mut socket, _) = listener.accept().await.expect("accept HTTP request");
                let mut buffer = vec![0u8; 1024 * 1024];
                let read = socket.read(&mut buffer).await.expect("read HTTP request");
                requests.push(String::from_utf8_lossy(&buffer[..read]).to_string());
                let response = format!(
                    "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                    body.len()
                );
                socket
                    .write_all(response.as_bytes())
                    .await
                    .expect("write HTTP response");
            }
            requests
        });

        let mut config = Config::default();
        config.api_url = format!("http://{addr}");
        config.api_key = Some("test-key".to_string());
        (ContextStreamClient::new(config), server)
    }

    #[tokio::test]
    async fn flash_get_forwards_same_instruction_session_project_switch() {
        let (client, server) = client_with_http_sequence(vec![
            ("200 OK", serde_json::json!({"entries": []}).to_string()),
            ("200 OK", serde_json::json!({"entries": []}).to_string()),
        ])
        .await;
        let workspace_id = Uuid::new_v4();
        let project_a = Uuid::new_v4();
        let project_b = Uuid::new_v4();

        for project_id in [project_a, project_b] {
            client
                .flash_get(FlashGetParams {
                    session_id: "same-instruction-session".to_string(),
                    workspace_id: Some(workspace_id),
                    project_id: Some(project_id),
                    limit: Some(20),
                })
                .await
                .expect("flash get request");
        }

        let requests = server.await.expect("flash get server task");
        assert_eq!(requests.len(), 2);
        for (request, project_id) in requests.iter().zip([project_a, project_b]) {
            assert!(request.starts_with("POST /api/v1/flash/get "));
            assert!(request.contains("\"session_id\":\"same-instruction-session\""));
            assert!(request.contains(&format!("\"workspace_id\":\"{workspace_id}\"")));
            assert!(request.contains(&format!("\"project_id\":\"{project_id}\"")));
        }
    }

