    #[tokio::test]
    async fn checkout_routing_scope_is_stable_path_free_and_installation_isolated() {
        let first_installation = Uuid::new_v4();
        let second_installation = Uuid::new_v4();
        let first = run_with_installation_id(first_installation, || async {
            ContextStreamClient::checkout_routing_scope("/Users/alice/dev/project/")
                .expect("routing scope")
        })
        .await;
        let normalized = run_with_installation_id(first_installation, || async {
            ContextStreamClient::checkout_routing_scope("/Users/alice/dev/./scratch/../project")
                .expect("routing scope")
        })
        .await;
        let other_installation = run_with_installation_id(second_installation, || async {
            ContextStreamClient::checkout_routing_scope("/Users/alice/dev/project")
                .expect("routing scope")
        })
        .await;

        assert_eq!(first, normalized);
        assert_ne!(first.checkout_locator, other_installation.checkout_locator);
        assert_eq!(first.installation_id, first_installation);
        assert!(first.checkout_locator.starts_with("checkout-locator-v1:"));
        assert!(!first.checkout_locator.contains("/Users/alice"));

        assert_eq!(
            ContextStreamClient::checkout_locator(
                first_installation,
                r"C:\Users\Alice\dev\project\.\src\..\"
            ),
            ContextStreamClient::checkout_locator(
                first_installation,
                r"\\?\C:\Users\Alice\dev\project"
            )
        );
        assert_eq!(
            ContextStreamClient::checkout_locator(
                first_installation,
                r"\\server\share\project\src\.."
            ),
            ContextStreamClient::checkout_locator(
                first_installation,
                r"\\?\UNC\server\share\project"
            )
        );
        assert!(
            ContextStreamClient::checkout_locator(first_installation, "relative/project").is_none()
        );
        assert!(
            ContextStreamClient::checkout_locator(first_installation, "/../../escape").is_none()
        );
    }

    #[tokio::test]
    async fn checkout_scoped_index_status_uses_opaque_query_and_requires_server_echo() {
        let project_id = Uuid::new_v4();
        let installation_id = Uuid::new_v4();
        let folder_path = "/Users/alice/dev/project-worktree";
        let locator = ContextStreamClient::checkout_locator(installation_id, folder_path).unwrap();
        let (client, server) = client_with_http_sequence(vec![
            (
                "200 OK",
                serde_json::json!({
                    "indexed_file_count": 41,
                    "checkout_scope": {
                        "installation_id": installation_id,
                        "checkout_locator": locator,
                        "matched": true,
                    }
                })
                .to_string(),
            ),
            (
                "200 OK",
                serde_json::json!({
                    "indexed_file_count": 41,
                })
                .to_string(),
            ),
        ])
        .await;

        let confirmed = run_with_installation_id(installation_id, || async {
            client
                .project_index_status_for_checkout(project_id, Some(folder_path))
                .await
        })
        .await
        .expect("scoped status");
        assert!(ContextStreamClient::project_index_status_matches_checkout(
            &confirmed
        ));

        let legacy = run_with_installation_id(installation_id, || async {
            client
                .project_index_status_for_checkout(project_id, Some(folder_path))
                .await
        })
        .await
        .expect("legacy status");
        assert!(ContextStreamClient::project_index_status_is_checkout_scoped(&legacy));
        assert!(!ContextStreamClient::project_index_status_matches_checkout(
            &legacy
        ));

        let requests = server.await.expect("index status request server");
        assert_eq!(requests.len(), 2);
        for request in requests {
            let request_line = request.lines().next().expect("request line");
            assert!(request_line.contains(&format!(
                "GET /api/v1/projects/{project_id}/index/status?installation_id={installation_id}&checkout_locator="
            )));
            assert!(request_line.contains("checkout-locator-v1%3A"));
            assert!(!request.contains(folder_path));
            assert!(!request.contains("/Users/alice"));
        }
    }

