    #[test]
    fn machine_identity_is_locked_stable_and_invalid_state_is_preserved() {
        let directory = tempfile::tempdir().expect("tempdir");
        let path = directory.path().join("machine-id");
        let first = ContextStreamClient::machine_id_at(&path).expect("first identity");
        let second = ContextStreamClient::machine_id_at(&path).expect("second identity");
        assert_eq!(first, second);
        assert_eq!(Uuid::parse_str(&first).unwrap().to_string(), first);

        let invalid_path = directory.path().join("invalid-machine-id");
        std::fs::write(&invalid_path, "not-a-machine-uuid").unwrap();
        assert!(ContextStreamClient::machine_id_at(&invalid_path).is_none());
        assert_eq!(
            std::fs::read_to_string(&invalid_path).unwrap(),
            "not-a-machine-uuid"
        );
    }

    #[cfg(unix)]
    #[test]
    fn machine_identity_never_follows_a_symlink() {
        use std::os::unix::fs::symlink;

        let directory = tempfile::tempdir().expect("tempdir");
        let target = directory.path().join("user-file");
        let link = directory.path().join("machine-id");
        std::fs::write(&target, "preserve-me").unwrap();
        symlink(&target, &link).unwrap();

        assert!(ContextStreamClient::machine_id_at(&link).is_none());
        assert_eq!(std::fs::read_to_string(&target).unwrap(), "preserve-me");
    }

    #[tokio::test]
    async fn sync_bridge_control_requests_are_path_free_and_lease_bound() {
        let project_id = Uuid::new_v4();
        let workspace_id = Uuid::new_v4();
        let installation_id = Uuid::new_v4();
        let bridge_instance_id = Uuid::new_v4();
        let checkout_id = format!("checkout-v1:{}", Uuid::new_v4());
        let request_id = "refresh-request-1";
        let lease_token = "opaque-lease-token";
        let (client, server) = client_with_http_sequence(vec![
            ("200 OK", "{}".to_string()),
            (
                "200 OK",
                serde_json::json!({
                    "requests": [{
                        "request_id": request_id,
                        "checkout_id": checkout_id,
                        "project_id": project_id,
                        "workspace_id": workspace_id,
                        "lease_token": lease_token,
                        "force": true,
                    }]
                })
                .to_string(),
            ),
            ("200 OK", "{}".to_string()),
            (
                "200 OK",
                serde_json::json!({"status": "completed"}).to_string(),
            ),
        ])
        .await;
        let registrations = vec![SyncBridgeCheckoutRegistration {
            checkout_id: checkout_id.clone(),
            checkout_locator: ContextStreamClient::checkout_locator(
                installation_id,
                "/Users/alice/dev/mcp-worktree",
            )
            .unwrap(),
            project_id,
            workspace_id,
            repository_fingerprint: "git-common-dir-v1:55555555-5555-4555-8555-555555555555"
                .to_string(),
            repository_identity: Some("git-remote-v1:github.com/acme/mcp".to_string()),
            git_ref_kind: "branch".to_string(),
            git_branch: Some("main".to_string()),
            git_commit_sha: Some("0123456789abcdef".to_string()),
            git_commit_timestamp: Some("2026-07-29T00:00:00Z".to_string()),
            is_default_branch: Some(true),
            dirty: Some(false),
            captured_at: "2026-07-29T00:00:01Z".to_string(),
        }];

        client
            .sync_bridge_heartbeat_with_identity(
                bridge_instance_id,
                installation_id,
                "machine-opaque-id",
                &registrations,
                "running",
            )
            .await
            .expect("heartbeat");
        let claims = client
            .claim_sync_bridge_refreshes_with_identity(
                bridge_instance_id,
                installation_id,
                "machine-opaque-id",
                &registrations,
                1,
                180,
            )
            .await
            .expect("claim");
        assert_eq!(claims.len(), 1);
        assert_eq!(claims[0].checkout_id, checkout_id);
        client
            .renew_sync_bridge_refresh(request_id, &checkout_id, lease_token, 180)
            .await
            .expect("renew");
        client
            .acknowledge_sync_bridge_refresh(
                request_id,
                &checkout_id,
                lease_token,
                "completed",
                None,
                Some(&serde_json::json!({
                    "committed": true,
                    "files_indexed": 3,
                })),
            )
            .await
            .expect("ack");

        let requests = server.await.expect("bridge control server");
        assert_eq!(requests.len(), 4);
        assert!(requests[0].contains("POST /api/v1/sync-bridge/heartbeat "));
        assert!(requests[1].contains("POST /api/v1/sync-bridge/refresh-requests/claim "));
        assert!(requests[2]
            .contains("POST /api/v1/sync-bridge/refresh-requests/refresh-request-1/heartbeat "));
        assert!(requests[3]
            .contains("POST /api/v1/sync-bridge/refresh-requests/refresh-request-1/ack "));
        for request in &requests {
            assert!(!request.contains("/Users/"));
            assert!(!request.contains("/home/"));
            assert!(!request.contains("local_root"));
        }
        let claim_body: serde_json::Value = serde_json::from_str(
            requests[1]
                .split_once("\r\n\r\n")
                .map(|(_, body)| body)
                .expect("claim body"),
        )
        .unwrap();
        assert_eq!(claim_body["installation_id"], installation_id.to_string());
        assert_eq!(claim_body["machine_id"], "machine-opaque-id");
        assert_eq!(claim_body["wait_seconds"], 20);
        assert_eq!(claim_body["checkouts"][0]["checkout_id"], checkout_id);
        assert_eq!(
            claim_body["checkouts"][0]["repository_identity"],
            "git-remote-v1:github.com/acme/mcp"
        );
        assert_eq!(claim_body["checkouts"][0]["git_branch"], "main");
    }

    async fn client_with_counted_http_behavior(
        response: Option<(&'static str, String)>,
    ) -> (
        ContextStreamClient,
        tokio::sync::oneshot::Sender<()>,
        tokio::task::JoinHandle<Vec<String>>,
    ) {
        use tokio::io::{AsyncReadExt, AsyncWriteExt};

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind counted HTTP listener");
        let addr = listener.local_addr().expect("counted HTTP listener addr");
        let (shutdown_tx, mut shutdown_rx) = tokio::sync::oneshot::channel();
        let server = tokio::spawn(async move {
            let mut requests = Vec::new();
            loop {
                tokio::select! {
                    _ = &mut shutdown_rx => break,
                    accepted = listener.accept() => {
                        let (mut socket, _) = accepted.expect("accept counted HTTP request");
                        let mut buffer = vec![0u8; 1024 * 1024];
                        let read = socket
                            .read(&mut buffer)
                            .await
                            .expect("read counted HTTP request");
                        requests.push(String::from_utf8_lossy(&buffer[..read]).to_string());
                        if let Some((status, body)) = response.as_ref() {
                            let response = format!(
                                "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                                body.len()
                            );
                            socket
                                .write_all(response.as_bytes())
                                .await
                                .expect("write counted HTTP response");
                        }
                    }
                }
            }
            requests
        });

        let mut config = Config::default();
        config.api_url = format!("http://{addr}");
        config.api_key = Some("test-key".to_string());
        (ContextStreamClient::new(config), shutdown_tx, server)
    }

    async fn assert_memory_search_makes_one_attempt_for_status(
        status: &'static str,
        expected_status: u16,
    ) {
        let (client, shutdown, server) = client_with_counted_http_behavior(Some((
            status,
            serde_json::json!({
                "error": {
                    "code": "memory_search_unavailable",
                    "message": "memory search unavailable"
                }
            })
            .to_string(),
        )))
        .await;

        let result = tokio::time::timeout(
            Duration::from_millis(750),
            client.search_memory(MemorySearchParams {
                query: format!("single-attempt-{status}"),
                ..MemorySearchParams::default()
            }),
        )
        .await
        .expect("memory-search response must not enter retry backoff");

        assert!(
            matches!(
                &result,
                Err(Error::Http { status, .. }) if *status == expected_status
            ),
            "the API must return the intended HTTP {expected_status} error, got {result:?}"
        );
        shutdown
            .send(())
            .expect("counted HTTP server must still be running");
        let requests = server.await.expect("counted HTTP server task");
        assert_eq!(
            requests.len(),
            1,
            "memory search must make exactly one API attempt for {status}"
        );
        assert!(
            requests[0].starts_with("POST /api/v1/memory/search "),
            "unexpected request line: {:?}",
            requests[0].lines().next()
        );
    }

    #[tokio::test]
    async fn account_context_auth_me_plan_skips_credit_balance_lookup() {
        use tokio::io::{AsyncReadExt, AsyncWriteExt};

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind account-context listener");
        let addr = listener
            .local_addr()
            .expect("account-context listener addr");
        let (shutdown_tx, mut shutdown_rx) = tokio::sync::oneshot::channel();
        let server = tokio::spawn(async move {
            let mut requests = Vec::new();
            loop {
                tokio::select! {
                    _ = &mut shutdown_rx => break,
                    accepted = listener.accept() => {
                        let (mut socket, _) = accepted.expect("accept account-context request");
                        let mut buffer = vec![0u8; 16 * 1024];
                        let read = socket
                            .read(&mut buffer)
                            .await
                            .expect("read account-context request");
                        let request = String::from_utf8_lossy(&buffer[..read]).to_string();
                        let request_line = request.lines().next().unwrap_or_default().to_string();
                        requests.push(request_line.clone());
                        let (status, body) =
                            if request_line.starts_with("GET /api/v1/account/context ") {
                                ("404 Not Found", "{}".to_string())
                            } else if request_line.starts_with("GET /api/v1/auth/me ") {
                                (
                                    "200 OK",
                                    serde_json::json!({
                                        "id": Uuid::new_v4(),
                                        "plan_name": "team"
                                    })
                                    .to_string(),
                                )
                            } else {
                                ("500 Internal Server Error", "{}".to_string())
                            };
                        let response = format!(
                            "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                            body.len()
                        );
                        socket
                            .write_all(response.as_bytes())
                            .await
                            .expect("write account-context response");
                    }
                }
            }
            requests
        });

        let mut config = Config::default();
        config.api_url = format!("http://{addr}");
        config.api_key = Some("test-key".to_string());
        let client = ContextStreamClient::new(config);

        let context = client
            .get_account_context()
            .await
            .expect("account context")
            .expect("fallback account context");
        assert_eq!(context.effective_plan.as_deref(), Some("team"));
        assert_eq!(context.account_type, "team");

        shutdown_tx
            .send(())
            .expect("account-context server must still be running");
        let requests = server.await.expect("account-context server task");
        assert_eq!(
            requests,
            vec![
                "GET /api/v1/account/context HTTP/1.1",
                "GET /api/v1/auth/me HTTP/1.1",
            ],
            "auth/me plan metadata must avoid an unnecessary /credits/balance request",
        );
    }

    #[tokio::test]
    async fn synthetic_probe_classification_is_typed_and_forwarded_on_all_request_paths() {
        let (client, server) = client_with_http_sequence(vec![
            ("200 OK", "{}".to_string()),
            ("200 OK", "ok".to_string()),
            ("200 OK", "{}".to_string()),
        ])
        .await;
        let forged_extra_header = Some(vec![(
            TrafficClass::HEADER_NAME.to_string(),
            "customer-controlled".to_string(),
        )]);

        run_with_auth_override(
            AuthOverride {
                api_key: Some("probe-key".to_string()),
                traffic_class: Some(TrafficClass::SyntheticProbe),
                ..Default::default()
            },
            || async {
                let _: serde_json::Value = client
                    .request::<serde_json::Value, serde_json::Value>(
                        "GET",
                        "/traffic-json",
                        None,
                        Some(RequestOptions {
                            retries: Some(0),
                            extra_headers: forged_extra_header.clone(),
                            ..Default::default()
                        }),
                    )
                    .await
                    .expect("typed JSON request");
                client
                    .request_text::<serde_json::Value>(
                        "GET",
                        "/traffic-text",
                        None,
                        Some(RequestOptions {
                            retries: Some(0),
                            extra_headers: forged_extra_header.clone(),
                            ..Default::default()
                        }),
                        Some("text/plain"),
                    )
                    .await
                    .expect("typed text request");
            },
        )
        .await;

        let _: serde_json::Value = client
            .request::<serde_json::Value, serde_json::Value>(
                "GET",
                "/traffic-forged-only",
                None,
                Some(RequestOptions {
                    retries: Some(0),
                    extra_headers: forged_extra_header,
                    ..Default::default()
                }),
            )
            .await
            .expect("ordinary JSON request");

        let requests = server.await.expect("traffic-class server task");
        assert_eq!(requests.len(), 3);
        for request in &requests[..2] {
            let request = request.to_ascii_lowercase();
            assert!(request.contains("x-contextstream-traffic-class: synthetic-probe\r\n"));
            assert!(request.contains("x-api-key: probe-key\r\n"));
            assert!(!request.contains("customer-controlled"));
        }
        let ordinary = requests[2].to_ascii_lowercase();
        assert!(!ordinary.contains("x-contextstream-traffic-class:"));
        assert!(!ordinary.contains("customer-controlled"));
    }

    fn assert_release_metadata_contract(metadata: &serde_json::Value) {
        let metadata = metadata
            .as_object()
            .expect("release metadata must always be an object");
        for key in [
            "version",
            "latest_version",
            "release_url",
            "release_metadata_source",
        ] {
            let value = metadata
                .get(key)
                .and_then(serde_json::Value::as_str)
                .unwrap_or_else(|| panic!("{key} must be a string"));
            assert!(!value.trim().is_empty(), "{key} must not be empty");
        }
    }

