    struct HomeEnvGuard(Option<std::ffi::OsString>);

    impl Drop for HomeEnvGuard {
        fn drop(&mut self) {
            if let Some(home) = self.0.take() {
                std::env::set_var("HOME", home);
            } else {
                std::env::remove_var("HOME");
            }
        }
    }

    fn initialize_bound_ingest_fixture(
        home: &Path,
        project_id: Uuid,
        workspace_id: Uuid,
    ) -> std::result::Result<std::path::PathBuf, Box<dyn std::error::Error>> {
        let root = home.join("repo");
        std::fs::create_dir_all(root.join(".contextstream"))?;
        let init = Command::new("git")
            .args(["init", "--quiet"])
            .arg(&root)
            .status()?;
        assert!(init.success());
        let marker_dir = root.join(".git").join("contextstream");
        std::fs::create_dir_all(&marker_dir)?;
        let fingerprint = format!("git-common-dir-v1:{}", Uuid::new_v4());
        std::fs::write(marker_dir.join("repository-id"), &fingerprint)?;
        std::fs::write(root.join("lib.rs"), "pub fn ready() -> bool { true }\n")?;
        std::fs::write(
            root.join(".contextstream").join("config.json"),
            serde_json::to_vec(&serde_json::json!({
                "workspace_id": workspace_id,
                "project_id": project_id,
                "checkout_root": std::fs::canonicalize(&root)?,
                "repository_fingerprint": fingerprint,
            }))?,
        )?;
        let checkout_guard = ContextStreamClient::local_checkout_guard(
            root.to_string_lossy().as_ref(),
            project_id,
            workspace_id,
        )?;
        let manifest_scope = ContextStreamClient::hash_manifest_scope(
            root.to_string_lossy().as_ref(),
            project_id,
            workspace_id,
            checkout_guard.as_deref(),
        )?;
        ContextStreamClient::register_hash_manifest_scope(
            root.to_string_lossy().as_ref(),
            &manifest_scope,
        );
        ContextStreamClient::write_hash_manifest(
            &manifest_scope,
            &std::collections::HashMap::from([(
                "lib.rs".to_string(),
                ContextStreamClient::sha256_hex("pub fn ready() -> bool { true }\n"),
            )]),
        );
        ContextStreamClient::write_verified_index_status(
            root.to_string_lossy().as_ref(),
            project_id,
            "previous-server-generation",
        );
        ContextStreamClient::mark_sensitive_cleanup_completed(project_id);
        Ok(root)
    }

    fn bound_manifest_scope(
        root: &Path,
        project_id: Uuid,
        workspace_id: Uuid,
    ) -> HashManifestScope {
        let checkout_guard = ContextStreamClient::local_checkout_guard(
            root.to_string_lossy().as_ref(),
            project_id,
            workspace_id,
        )
        .expect("read checkout guard");
        ContextStreamClient::hash_manifest_scope(
            root.to_string_lossy().as_ref(),
            project_id,
            workspace_id,
            checkout_guard.as_deref(),
        )
        .expect("build manifest scope")
    }

