    fn pending_scan_receipt_fixture(
        root: &Path,
        project_id: Uuid,
        workspace_id: Uuid,
        base: &HashManifestData,
        desired: &HashManifestData,
        page_paths: Vec<String>,
    ) -> (std::path::PathBuf, PendingScanPageReceipt) {
        let root = std::fs::canonicalize(root).expect("canonical test checkout");
        let root_text = root.to_string_lossy().to_string();
        let scope =
            ContextStreamClient::hash_manifest_scope(&root_text, project_id, workspace_id, None)
                .expect("manifest scope");
        let cursor_scope = ContextStreamClient::scan_cursor_scope(project_id, workspace_id, None);
        let cursor_path =
            ContextStreamClient::scan_cursor_path(&root_text, &cursor_scope).expect("cursor path");
        let receipt_path =
            ContextStreamClient::pending_scan_receipt_path(&root_text, project_id, workspace_id)
                .expect("receipt path");
        let receipt = PendingScanPageReceipt {
            version: 1,
            fingerprint_semantics: Some(FINGERPRINT_SEMANTICS_RACY_CLEAN_V1.to_string()),
            receipt_id: Uuid::new_v4(),
            project_id,
            workspace_id,
            checkout_root: root_text,
            checkout_guard: None,
            manifest_scope: scope,
            manifest_patch: ContextStreamClient::hash_manifest_patch(base, desired),
            cursor_update: ScanCursorUpdate::Set {
                seen_path: ContextStreamClient::scan_epoch_seen_path(&cursor_path),
                path: cursor_path,
                value: "src/b.rs".to_string(),
                page_paths,
                valid: true,
                reset_seen: true,
            },
            job_ids: vec![Uuid::new_v4()],
            scan_complete: false,
            sensitive_cleanup_pending: false,
            created_at: Utc::now().to_rfc3339(),
        };
        (receipt_path, receipt)
    }

    #[test]
    fn legacy_pending_scan_receipt_still_matches_scope_for_job_quiescence() {
        let root = tempfile::tempdir().expect("receipt fixture");
        let project_id = Uuid::new_v4();
        let workspace_id = Uuid::new_v4();
        let (_, receipt) = pending_scan_receipt_fixture(
            root.path(),
            project_id,
            workspace_id,
            &HashManifestData::default(),
            &HashManifestData::default(),
            vec!["src/a.rs".to_string()],
        );
        assert!(ContextStreamClient::pending_scan_receipt_matches_scope(
            &receipt,
            project_id,
            workspace_id,
            &receipt.checkout_root,
            None,
            &receipt.manifest_scope,
        ));

        let mut legacy = receipt.clone();
        legacy.fingerprint_semantics = None;
        assert!(ContextStreamClient::pending_scan_receipt_matches_scope(
            &legacy,
            project_id,
            workspace_id,
            &legacy.checkout_root,
            None,
            &legacy.manifest_scope,
        ));
    }

    #[allow(clippy::await_holding_lock)]
    #[tokio::test(flavor = "current_thread")]
    async fn legacy_pending_scan_receipt_waits_for_jobs_then_resets_without_patch_replay() {
        let _guard = env_test_mutex()
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let _home_guard = HomeEnvGuard(std::env::var_os("HOME"));
        let temp_home = std::env::temp_dir().join(format!(
            "contextstream-legacy-receipt-quiescence-{}",
            Uuid::new_v4()
        ));
        let root = temp_home.join("checkout");
        std::fs::create_dir_all(&root).expect("checkout");
        std::env::set_var("HOME", &temp_home);
        let project_id = Uuid::new_v4();
        let workspace_id = Uuid::new_v4();
        let unsafe_desired = HashManifestData {
            hashes: std::collections::HashMap::from([(
                "src/a.rs".to_string(),
                "legacy-stale-hash".to_string(),
            )]),
            fingerprints: std::collections::HashMap::from([(
                "src/a.rs".to_string(),
                LocalFileFingerprint {
                    size: 5,
                    modified_seconds: 10,
                    modified_nanoseconds: 20,
                    changed_seconds: 10,
                    changed_nanoseconds: 20,
                    device: 1,
                    inode: 2,
                    mode: 0o100644,
                },
            )]),
        };
        let (receipt_path, mut receipt) = pending_scan_receipt_fixture(
            &root,
            project_id,
            workspace_id,
            &HashManifestData::default(),
            &unsafe_desired,
            vec!["src/a.rs".to_string()],
        );
        receipt.fingerprint_semantics = None;
        ContextStreamClient::persist_pending_scan_receipt(&receipt_path, &receipt)
            .expect("persist legacy receipt");

        let (pending_client, pending_server) = client_with_http_sequence(vec![(
            "200 OK",
            serde_json::json!({
                "status": "processing",
                "files_total": 1,
                "files_processed": 0,
            })
            .to_string(),
        )])
        .await;
        let pending = pending_client
            .reconcile_pending_scan_receipt(
                &receipt.checkout_root,
                project_id,
                workspace_id,
                &receipt.checkout_root,
                None,
                &receipt.manifest_scope,
            )
            .await
            .expect("poll pending legacy job");
        assert!(matches!(
            pending,
            PendingScanReceiptReconcile::Pending { .. }
        ));
        assert!(
            receipt_path.exists(),
            "live legacy receipt must remain durable"
        );
        pending_server.await.expect("pending mock server");

        let status = primary_attestation_fixture(project_id, workspace_id, 44, 'd');
        let (completed_client, completed_server) = client_with_http_sequence(vec![
            (
                "200 OK",
                serde_json::json!({
                    "status": "completed",
                    "files_total": 1,
                    "files_processed": 1,
                })
                .to_string(),
            ),
            ("200 OK", status.to_string()),
        ])
        .await;
        let completed = completed_client
            .reconcile_pending_scan_receipt(
                &receipt.checkout_root,
                project_id,
                workspace_id,
                &receipt.checkout_root,
                None,
                &receipt.manifest_scope,
            )
            .await
            .expect("quiesce terminal legacy job");
        assert!(matches!(completed, PendingScanReceiptReconcile::Reset));
        assert!(!receipt_path.exists());
        assert!(
            ContextStreamClient::read_hash_manifest_data(&receipt.manifest_scope)
                .hashes
                .is_empty()
        );
        completed_server.await.expect("completed mock server");

        let _ = std::fs::remove_dir_all(temp_home);
    }

    #[test]
    fn local_indexing_started_marker_preserves_committed_timestamp_until_success() {
        let _guard = env_test_mutex().lock().unwrap_or_else(|e| e.into_inner());
        let _home_guard = HomeEnvGuard(std::env::var_os("HOME"));
        let temp_home = std::env::temp_dir().join(format!(
            "contextstream-client-index-marker-{}-{}",
            std::process::id(),
            chrono::Utc::now().timestamp_nanos_opt().unwrap_or_default()
        ));
        std::fs::create_dir_all(&temp_home).unwrap();
        std::env::set_var("HOME", &temp_home);

        let project_id = Uuid::new_v4();
        let folder = temp_home.join("repo");
        std::fs::create_dir_all(&folder).unwrap();
        let folder = folder.to_string_lossy().to_string();
        let committed_at = Utc::now() - chrono::Duration::hours(72);

        ContextStreamClient::write_index_status_at(&folder, project_id, committed_at);
        ContextStreamClient::write_indexing_started(&folder, project_id);

        let started_at =
            ContextStreamClient::local_indexing_started_at(&folder).expect("started marker");
        assert!(started_at > committed_at);
        let indexed_at = ContextStreamClient::local_indexed_at(&folder).expect("indexed timestamp");
        assert!(indexed_at <= committed_at + chrono::Duration::seconds(1));

        let completed_at = Utc::now();
        ContextStreamClient::write_index_status_at(&folder, project_id, completed_at);

        assert!(ContextStreamClient::local_indexing_started_at(&folder).is_none());
        let indexed_at = ContextStreamClient::local_indexed_at(&folder).expect("indexed timestamp");
        assert!(indexed_at >= completed_at - chrono::Duration::seconds(1));

        ContextStreamClient::write_verified_index_status(
            &folder,
            project_id,
            "server-generation-proof",
        );
        assert_eq!(
            ContextStreamClient::local_server_index_attestation(&folder).as_deref(),
            Some("server-generation-proof")
        );
        ContextStreamClient::write_index_status(&folder, project_id);
        assert_eq!(
            ContextStreamClient::local_server_index_attestation(&folder).as_deref(),
            Some("server-generation-proof"),
            "generic committed refresh preserves the proof for mismatch detection"
        );
        ContextStreamClient::write_index_status_at(&folder, project_id, Utc::now());
        assert!(ContextStreamClient::local_server_index_attestation(&folder).is_none());

        let _ = std::fs::remove_dir_all(temp_home);
    }

    #[test]
    fn server_attestation_only_refresh_preserves_folder_coverage_fields() {
        let _guard = env_test_mutex().lock().unwrap_or_else(|e| e.into_inner());
        let _home_guard = HomeEnvGuard(std::env::var_os("HOME"));
        let temp_home =
            std::env::temp_dir().join(format!("contextstream-attestation-only-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&temp_home).expect("temp home");
        std::env::set_var("HOME", &temp_home);
        let project_id = Uuid::new_v4();
        let folder = temp_home.join("repo");
        std::fs::create_dir_all(&folder).expect("checkout");
        std::fs::write(folder.join("tracked.rs"), "pub fn tracked() {}\n").expect("source");
        let folder_text = folder.to_string_lossy().to_string();

        ContextStreamClient::write_verified_index_status(
            &folder_text,
            project_id,
            "generation-before",
        );
        ContextStreamClient::write_indexing_started(&folder_text, project_id);
        let (_, before) =
            ContextStreamClient::best_local_index_entry(&folder_text).expect("initial index entry");
        ContextStreamClient::write_server_index_attestation_only(
            &folder_text,
            project_id,
            "generation-after",
        );
        let (_, after) =
            ContextStreamClient::best_local_index_entry(&folder_text).expect("updated index entry");

        assert_eq!(after["server_index_attestation"], "generation-after");
        assert_eq!(after.get("indexed_at"), before.get("indexed_at"));
        assert_eq!(after.get("indexed_commit"), before.get("indexed_commit"));
        assert_eq!(
            after.get("indexing_started_at"),
            before.get("indexing_started_at")
        );

        let _ = std::fs::remove_dir_all(temp_home);
    }

    #[test]
    fn pending_scan_receipt_survives_restart_and_commits_exact_page_state() {
        let _guard = env_test_mutex().lock().unwrap_or_else(|e| e.into_inner());
        let _home_guard = HomeEnvGuard(std::env::var_os("HOME"));
        let temp_home =
            std::env::temp_dir().join(format!("contextstream-receipt-restart-{}", Uuid::new_v4()));
        let root = temp_home.join("repo");
        std::fs::create_dir_all(&root).expect("checkout");
        std::env::set_var("HOME", &temp_home);
        let project_id = Uuid::new_v4();
        let workspace_id = Uuid::new_v4();
        let base = HashManifestData::default();
        let desired = HashManifestData {
            hashes: std::collections::HashMap::from([
                ("src/a.rs".to_string(), "hash-a".to_string()),
                ("src/b.rs".to_string(), "hash-b".to_string()),
            ]),
            fingerprints: Default::default(),
        };
        let (receipt_path, receipt) = pending_scan_receipt_fixture(
            &root,
            project_id,
            workspace_id,
            &base,
            &desired,
            vec!["src/a.rs".to_string(), "src/b.rs".to_string()],
        );
        ContextStreamClient::persist_pending_scan_receipt(&receipt_path, &receipt)
            .expect("persist receipt");

        // Read the receipt back from disk as a new process/session would, then
        // finalize only the state encoded in that durable acknowledgement.
        let restarted = ContextStreamClient::read_pending_scan_receipt(&receipt_path)
            .expect("read receipt")
            .expect("receipt exists");
        ContextStreamClient::finalize_pending_scan_receipt(&receipt_path, &restarted)
            .expect("finalize receipt");

        assert!(!receipt_path.exists());
        assert_eq!(
            ContextStreamClient::read_hash_manifest_data(&receipt.manifest_scope).hashes,
            desired.hashes
        );
        let cursor_path = ContextStreamClient::scan_cursor_update_path(&receipt.cursor_update)
            .expect("cursor path");
        let cursor = ContextStreamClient::read_scan_epoch(Some(cursor_path)).expect("cursor state");
        assert_eq!(cursor.cursor, "src/b.rs");
        assert_eq!(cursor.applied_receipt_id, Some(receipt.receipt_id));

        let _ = std::fs::remove_dir_all(temp_home);
    }

