    #[test]
    fn started_only_marker_tracks_project_without_reporting_ready_index() {
        let _guard = env_test_mutex().lock().unwrap_or_else(|e| e.into_inner());
        let _home_guard = HomeEnvGuard(std::env::var_os("HOME"));
        let temp_home = std::env::temp_dir().join(format!(
            "contextstream-client-index-started-only-{}-{}",
            std::process::id(),
            chrono::Utc::now().timestamp_nanos_opt().unwrap_or_default()
        ));
        std::fs::create_dir_all(&temp_home).unwrap();
        std::env::set_var("HOME", &temp_home);

        let project_id = Uuid::new_v4();
        let folder = temp_home.join("repo");
        std::fs::create_dir_all(&folder).unwrap();
        let folder = folder.to_string_lossy().to_string();

        ContextStreamClient::write_indexing_started(&folder, project_id);

        assert!(
            !ContextStreamClient::is_project_indexed(&folder),
            "started-only metadata must not be reported as search-ready"
        );
        assert_eq!(
            ContextStreamClient::indexed_project_id_for_folder(&folder),
            None,
            "ready project lookup requires a committed indexed_at timestamp"
        );
        assert_eq!(
            ContextStreamClient::tracked_project_id_for_folder(&folder),
            Some(project_id),
            "scope alignment should still use a recent in-progress marker"
        );

        let _ = std::fs::remove_dir_all(temp_home);
    }

    #[test]
    fn local_index_entry_readiness_requires_recent_committed_timestamp() {
        let ready = serde_json::json!({
            "indexed_at": (Utc::now() - chrono::Duration::hours(1)).to_rfc3339()
        });
        let barely_ready = serde_json::json!({
            "indexed_at": (Utc::now()
                - chrono::Duration::seconds(LOCAL_INDEX_READY_MAX_AGE_SECS - 1))
            .to_rfc3339()
        });
        let stale = serde_json::json!({
            "indexed_at": (Utc::now()
                - chrono::Duration::seconds(LOCAL_INDEX_READY_MAX_AGE_SECS + 1))
            .to_rfc3339()
        });
        let started_only = serde_json::json!({
            "indexing_started_at": Utc::now().to_rfc3339()
        });
        let malformed = serde_json::json!({
            "indexed_at": "not-a-timestamp"
        });

        assert!(ContextStreamClient::index_entry_is_ready(&ready));
        assert!(ContextStreamClient::index_entry_is_ready(&barely_ready));
        assert!(!ContextStreamClient::index_entry_is_ready(&stale));
        assert!(!ContextStreamClient::index_entry_is_ready(&started_only));
        assert!(!ContextStreamClient::index_entry_is_ready(&malformed));
        assert!(ContextStreamClient::index_entry_is_trackable(&started_only));
    }

    #[tokio::test]
    async fn set_defaults_no_ops_inside_task_auth_scope() {
        // Multi-tenant safety regression guard. On the hosted gateway,
        // every request runs inside `run_with_auth_override`. If
        // `set_defaults` writes to the process-global `Config` while
        // inside that scope, the resolved IDs from one request leak into
        // every concurrent / subsequent request's fallback reads — that
        // was the symptom behind the project-switching bug (folder=X
        // returning project=<previous user's project>).
        let client = ContextStreamClient::new(Config::default());
        let user_a_ws = Uuid::new_v4();
        let user_a_proj = Uuid::new_v4();

        run_with_auth_override(
            AuthOverride {
                api_key: Some("test-key".into()),
                jwt: None,
                workspace_id: Some(user_a_ws),
                project_id: None,
                traffic_class: None,
            },
            || async {
                client
                    .set_defaults(Some(user_a_ws), Some(user_a_proj))
                    .await;
            },
        )
        .await;

        // Outside the auth scope, the global config must NOT have been
        // mutated by user A's set_defaults call.
        let config_after = client.config().await;
        assert!(
            config_after.default_workspace_id.is_none(),
            "set_defaults must not write workspace_id to global Config inside an auth scope"
        );
        assert!(
            config_after.default_project_id.is_none(),
            "set_defaults must not write project_id to global Config inside an auth scope"
        );
    }

    #[tokio::test]
    async fn set_defaults_writes_global_outside_task_auth_scope() {
        // Single-tenant CLI / stdio path: no auth scope active, so
        // set_defaults should still mutate the process-global Config so
        // subsequent calls in the same process inherit the resolved IDs.
        let client = ContextStreamClient::new(Config::default());
        let ws = Uuid::new_v4();
        let proj = Uuid::new_v4();

        client.set_defaults(Some(ws), Some(proj)).await;

        let config_after = client.config().await;
        assert_eq!(config_after.default_workspace_id, Some(ws));
        assert_eq!(config_after.default_project_id, Some(proj));
    }

