    #[test]
    fn vcs_local_event_body_enforces_privacy_boundary() {
        let checkout_id = Uuid::new_v4();
        let project_id = Uuid::new_v4();
        let body = vcs_local_event_body(
            CaptureVcsLocalEventParams {
                event_type: "commit.local".to_string(),
                remote_url: Some(
                    "https://user:password@GitHub.COM/ContextStream/MCP-Server.git?token=secret#fragment"
                        .to_string(),
                ),
                repo_path: Some(format!("checkout-v1:{checkout_id}")),
                sha: Some("ABCDEF0123456789".to_string()),
                message: Some(
                    "Fix /home/alice/project for alice@example.com token=super-secret\nprivate body"
                        .to_string(),
                ),
                author_name: Some("Alice Example".to_string()),
                author_email: Some("alice@example.com".to_string()),
                branch: Some("feature/privacy-boundary".to_string()),
                additions: Some(5),
                deletions: Some(-1),
                files_changed: Some(2),
                committed_at: Some("2026-08-31T12:34:56Z".to_string()),
                ..Default::default()
            },
            Some(project_id),
        )
        .expect("valid event");

        assert_eq!(body["repo_path"], format!("checkout-v1:{checkout_id}"));
        assert_eq!(
            body["remote_url"],
            "https://github.com/ContextStream/MCP-Server.git"
        );
        assert_eq!(body["sha"], "abcdef0123456789");
        assert_eq!(body["project_id"], project_id.to_string());
        assert_eq!(body["additions"], 5);
        assert!(body.get("deletions").is_none());
        assert!(body.get("author_name").is_none());
        assert!(body.get("author_email").is_none());

        let message = body["message"].as_str().expect("sanitized message");
        assert!(message.contains("[redacted-path]"));
        assert!(message.contains("[redacted-email]"));
        assert!(message.contains("[redacted-secret]"));
        assert!(!message.contains("private body"));
        assert!(!message.contains("alice@example.com"));
        assert!(!message.contains("super-secret"));

        let serialized = body.to_string();
        assert!(!serialized.contains("user:password"));
        assert!(!serialized.contains("token=secret"));
        assert!(!serialized.contains("/home/alice"));
    }

