    #[test]
    fn folder_matches_index_scope_resolves_symlinked_paths(
    ) -> std::result::Result<(), Box<dyn std::error::Error>> {
        let temp = std::env::temp_dir().join(format!("mcp-client-{}", Uuid::new_v4()));
        let real_root = temp.join("real-root");
        let linked_root = temp.join("linked-root");
        let real_project = real_root.join("maker");
        let real_child = real_project.join("contextstream");
        std::fs::create_dir_all(&real_child)?;

        #[cfg(unix)]
        std::os::unix::fs::symlink(&real_project, &linked_root)?;
        #[cfg(windows)]
        std::os::windows::fs::symlink_dir(&real_project, &linked_root)?;

        assert!(ContextStreamClient::folder_matches_index_scope(
            real_child.to_string_lossy().as_ref(),
            linked_root.to_string_lossy().as_ref()
        ));

        std::fs::remove_dir_all(&temp)?;
        Ok(())
    }

