    #[tokio::test]
    async fn list_all_projects_fetches_projects_beyond_the_first_page() {
        let workspace_id = Uuid::new_v4();
        let first_page: Vec<_> = (0..200)
            .map(|index| {
                serde_json::json!({
                    "id": Uuid::from_u128(index + 1),
                    "name": format!("project-{index}")
                })
            })
            .collect();
        let final_project_id = Uuid::from_u128(201);
        let (client, server) = client_with_http_sequence(vec![
            (
                "200 OK",
                serde_json::json!({
                    "items": first_page,
                    "page": 1,
                    "page_size": 200,
                    "total": 201,
                    "total_pages": 2,
                    "has_next": true
                })
                .to_string(),
            ),
            (
                "200 OK",
                serde_json::json!({
                    "items": [{
                        "id": final_project_id,
                        "name": "project-200"
                    }],
                    "page": 2,
                    "page_size": 200,
                    "total": 201,
                    "total_pages": 2,
                    "has_next": false
                })
                .to_string(),
            ),
        ])
        .await;

        let projects = client
            .list_all_projects(Some(workspace_id), 200, 100_000)
            .await
            .expect("list all projects");
        let requests = server.await.expect("HTTP sequence server");

        assert_eq!(projects.len(), 201);
        assert_eq!(
            projects.last().map(|project| project.id),
            Some(final_project_id)
        );
        assert_eq!(requests.len(), 2);
        assert!(requests[0].contains("page=1"));
        assert!(requests[1].contains("page=2"));
    }

    #[tokio::test]
    async fn list_all_projects_fails_closed_when_pagination_makes_no_progress() {
        let project_id = Uuid::new_v4();
        let page = |page_number| {
            serde_json::json!({
                "items": [{
                    "id": project_id,
                    "name": "same-project"
                }],
                "page": page_number,
                "page_size": 1,
                "has_next": true
            })
            .to_string()
        };
        let (client, server) =
            client_with_http_sequence(vec![("200 OK", page(1)), ("200 OK", page(2))]).await;

        let error = client
            .list_all_projects(None, 1, 100)
            .await
            .expect_err("duplicate project pages must fail");
        let requests = server.await.expect("HTTP sequence server");

        assert!(error.to_string().contains("made no progress"));
        assert_eq!(requests.len(), 2);
    }

