    #[test]
    fn help_tools_includes_instruction_and_skill_surfaces() {
        let client = ContextStreamClient::new(Config::default());
        let tools = tokio::runtime::Runtime::new()
            .expect("runtime")
            .block_on(client.help_tools(None, None))
            .expect("help tools");

        let names = tools["tools"]
            .as_array()
            .map(|items| {
                items
                    .iter()
                    .filter_map(|tool| tool.get("name").and_then(|value| value.as_str()))
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();

        // Canonical catalog: 22 tools (coordination added in v0.5.93, feed
        // added with Context Feeds).
        // Aliases atlas_chart / atlas_job remain accepted at call-time for
        // back-compat but are intentionally absent. The dropped `ram` alias
        // must NOT reappear.
        assert_eq!(names.len(), 22);
        assert!(names.contains(&"instruct"));
        assert!(names.contains(&"skill"));
        assert!(names.contains(&"capsule"));
        assert!(names.contains(&"qa"));
        assert!(names.contains(&"entity"));
        assert!(names.contains(&"coordination"));
        assert!(names.contains(&"feed"));
        assert!(names.contains(&"vcs"));
        assert!(names.contains(&"chart"));
        assert!(names.contains(&"async_job"));
        assert!(!names.contains(&"ram"));
        assert!(!names.contains(&"atlas_chart"));
        assert!(!names.contains(&"atlas_job"));

        // No description should leak internal stack names.
        let descriptions = tools["tools"]
            .as_array()
            .map(|items| {
                items
                    .iter()
                    .filter_map(|t| t.get("description").and_then(|v| v.as_str()))
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        for desc in descriptions {
            let low = desc.to_lowercase();
            assert!(!low.contains("mongodb"), "leaks 'mongodb': {}", desc);
            assert!(!low.contains("atlas"), "leaks 'atlas': {}", desc);
            assert!(!low.contains("voyage"), "leaks 'voyage': {}", desc);
            assert!(!low.contains("qdrant"), "leaks 'qdrant': {}", desc);
            assert!(!low.contains("friendli"), "leaks 'friendli': {}", desc);
            assert!(!low.contains("glm"), "leaks 'glm': {}", desc);
            assert!(!low.contains("zai-org"), "leaks 'zai-org': {}", desc);
        }
    }

