    #[tokio::test]
    async fn memory_search_does_not_retry_transport_failure() {
        let (client, shutdown, server) = client_with_counted_http_behavior(None).await;

        let result = tokio::time::timeout(
            Duration::from_millis(750),
            client.search_memory(MemorySearchParams {
                query: "single-attempt-transport-failure".to_string(),
                ..MemorySearchParams::default()
            }),
        )
        .await
        .expect("transport failure must not enter retry backoff");

        assert!(
            matches!(&result, Err(Error::Network(_))),
            "the connection close must return a transport error, got {result:?}"
        );
        shutdown
            .send(())
            .expect("counted HTTP server must still be running");
        let requests = server.await.expect("counted HTTP server task");
        assert_eq!(
            requests.len(),
            1,
            "memory search must make exactly one API attempt after a transport failure"
        );
        assert!(
            requests[0].starts_with("POST /api/v1/memory/search "),
            "unexpected request line: {:?}",
            requests[0].lines().next()
        );
    }

    #[tokio::test]
    async fn memory_search_preserves_one_immediate_403_refresh_replay() {
        let (client, server) = client_with_http_sequence(vec![
            (
                "403 Forbidden",
                serde_json::json!({
                    "error": {"code": "forbidden", "message": "session scope is stale"}
                })
                .to_string(),
            ),
            (
                "200 OK",
                serde_json::json!({"data": {"results": [], "total": 0}}).to_string(),
            ),
        ])
        .await;
        let refreshes = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let refreshes_for_hook = Arc::clone(&refreshes);
        client
            .set_session_refresh_hook(Arc::new(move || {
                let refreshes = Arc::clone(&refreshes_for_hook);
                Box::pin(async move {
                    refreshes.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                    true
                })
            }))
            .await;

        let result = tokio::time::timeout(
            Duration::from_millis(750),
            client.search_memory(MemorySearchParams {
                query: "refresh scope".to_string(),
                ..MemorySearchParams::default()
            }),
        )
        .await
        .expect("auth refresh replay must not wait for status backoff")
        .expect("the one auth refresh replay should reach the healthy response");

        assert_eq!(result["total"], 0);
        assert_eq!(refreshes.load(std::sync::atomic::Ordering::SeqCst), 1);
        let requests = server.await.expect("memory-search server task");
        assert_eq!(requests.len(), 2);
    }

    #[tokio::test]
    async fn memory_search_does_not_cache_nested_api_degradation() {
        let degraded = serde_json::json!({
            "success": true,
            "data": {
                "results": [],
                "total": 0,
                "degraded": true,
                "degraded_reason": "vector_timeout"
            }
        });
        let (client, server) = client_with_http_sequence(vec![
            ("200 OK", degraded.to_string()),
            ("200 OK", degraded.to_string()),
        ])
        .await;
        let query = format!("degraded-cache-{}", Uuid::new_v4());

        let (first, second) = run_with_session_key(SessionKey::Local, || async {
            let params = MemorySearchParams {
                query,
                ..MemorySearchParams::default()
            };
            let first = client
                .search_memory(params.clone())
                .await
                .expect("first degraded response");
            let second = client
                .search_memory(params)
                .await
                .expect("second degraded response");
            (first, second)
        })
        .await;

        assert!(ContextStreamClient::memory_search_response_is_degraded(
            &first
        ));
        assert!(ContextStreamClient::memory_search_response_is_degraded(
            &second
        ));
        let requests = server.await.expect("memory-search server task");
        assert_eq!(
            requests.len(),
            2,
            "degraded success responses must not enter the client cache"
        );
    }

