    #[test]
    fn parse_ingest_batch_result_extracts_job_metadata() {
        let project_id = Uuid::nil();
        let batch = ContextStreamClient::parse_ingest_batch_result(
            serde_json::json!({
                "files_indexed": 0,
                "committed": false,
                "job_id": "11111111-1111-1111-1111-111111111111",
                "progress_url": "/api/v1/projects/00000000-0000-0000-0000-000000000000/ingest/jobs/11111111-1111-1111-1111-111111111111"
            }),
            project_id,
            vec!["src/lib.rs".to_string(), "src/main.rs".to_string()],
        )
        .expect("valid queued contract");

        assert_eq!(batch.files_indexed, 0);
        assert!(!batch.committed);
        assert_eq!(
            batch.job_id,
            Some(Uuid::parse_str("11111111-1111-1111-1111-111111111111").expect("valid uuid"))
        );
        assert_eq!(
            batch.progress_url.as_deref(),
            Some(
                "/api/v1/projects/00000000-0000-0000-0000-000000000000/ingest/jobs/11111111-1111-1111-1111-111111111111"
            )
        );
        assert_eq!(batch.file_paths.len(), 2);
    }

    #[test]
    fn parse_ingest_batch_result_fails_closed_on_ambiguous_commit_state() {
        let project_id = Uuid::nil();
        let parse = |value| {
            ContextStreamClient::parse_ingest_batch_result(
                value,
                project_id,
                vec!["src/lib.rs".to_string()],
            )
        };
        assert!(parse(serde_json::json!({"files_indexed": 1})).is_err());
        assert!(parse(serde_json::json!({
            "committed": false,
            "job_id": "not-a-uuid"
        }))
        .is_err());
        assert!(parse(serde_json::json!({"committed": false})).is_err());
        assert!(parse(serde_json::json!({
            "committed": true,
            "files_indexed": 1,
            "job_id": Uuid::new_v4()
        }))
        .is_err());
        assert!(parse(serde_json::json!({
            "status": "partial",
            "committed": true,
            "files_indexed": 1,
            "errors": 1
        }))
        .is_err());
        assert!(parse(serde_json::json!({
            "status": "success",
            "committed": false,
            "job_id": Uuid::new_v4(),
            "failed_paths": ["src/lib.rs"]
        }))
        .is_err());
        let committed = parse(serde_json::json!({
            "committed": true,
            "files_indexed": 1
        }))
        .expect("explicit sync contract");
        assert!(committed.committed);
        assert_eq!(committed.files_indexed, 1);
    }

