    #[cfg(unix)]
    #[test]
    fn targeted_file_payload_rejects_symlink_escape() {
        use std::os::unix::fs::symlink;

        let base = std::env::temp_dir().join(format!("mcp-client-link-{}", Uuid::new_v4()));
        let root = base.join("repo");
        let outside = base.join("outside");
        std::fs::create_dir_all(&root).expect("root");
        std::fs::create_dir_all(&outside).expect("outside");
        std::fs::write(outside.join("secret.rs"), "const SECRET: &str = \"no\";\n")
            .expect("secret");
        symlink(&outside, root.join("link")).expect("symlink");

        assert!(ContextStreamClient::targeted_text_file_payload(
            root.to_string_lossy().as_ref(),
            root.join("link/secret.rs").to_string_lossy().as_ref(),
        )
        .is_none());
        assert!(ContextStreamClient::safe_project_relative_path(
            root.to_string_lossy().as_ref(),
            root.join("link/missing.rs").to_string_lossy().as_ref(),
            false,
        )
        .is_none());

        std::fs::remove_dir_all(base).expect("cleanup");
    }

    #[test]
    fn prepare_changed_file_payloads_compacts_large_text_files() {
        let file = serde_json::json!({
            "path": "src/big.rs",
            "language": "rust",
            "content": format!(
                "{}\npub fn important_middle_symbol() {{}}\n{}",
                "fn prefix_symbol() {}\n".repeat(400),
                "fn suffix_symbol() {}\n".repeat(400),
            ),
        });

        let prepared = ContextStreamClient::prepare_changed_file_payloads(vec![&file], 4096);

        assert_eq!(prepared.compacted_files, 1);
        assert!(prepared.deferred_paths.is_empty());
        assert_eq!(prepared.files.len(), 1);

        let compacted = prepared.files[0].as_ref();
        let compacted_content = compacted
            .get("content")
            .and_then(|value| value.as_str())
            .expect("compacted content");

        assert!(ContextStreamClient::estimated_payload_size(compacted) <= 4096);
        assert!(compacted_content.contains("important_middle_symbol"));
        assert!(compacted_content.contains("--- FILE PREFIX ---"));
        assert!(compacted_content.contains("--- FILE SUFFIX ---"));
    }

    #[test]
    fn prepare_changed_file_payloads_defers_oversized_binary_files() {
        let file = serde_json::json!({
            "path": "assets/large.png",
            "content": "A".repeat(4096),
            "content_type": "image/png",
            "encoding": "base64"
        });

        let prepared = ContextStreamClient::prepare_changed_file_payloads(vec![&file], 512);

        assert_eq!(prepared.compacted_files, 0);
        assert!(prepared.files.is_empty());
        assert_eq!(prepared.deferred_paths, vec!["assets/large.png"]);
    }

    #[test]
    fn estimated_payload_size_matches_real_json_size_for_ingest_file() {
        let file = serde_json::json!({
            "path": "src/example.ts",
            "content": "export const value = \"quoted\\ntext\";\n",
            "language": "typescript"
        });

        let estimated = ContextStreamClient::estimated_payload_size(&file);
        let actual = serde_json::to_vec(&file).expect("serialize").len();

        assert_eq!(estimated, actual);
    }

