/// Opt-in filesystem scanner benchmark for repository sizes that are too large
/// for the normal unit-test suite. Run with, for example:
///
/// `CONTEXTSTREAM_HUGE_SCAN_FILE_COUNTS=10k,100k,1m cargo test -p mcp-client huge_repository_cold_warm_scan_benchmark -- --ignored --nocapture`
///
/// Any positive count up to one million is accepted so CI and local smoke runs
/// can use a smaller fixture before running the standard 10k/100k/1m presets.
#[cfg(all(test, any(target_os = "linux", target_os = "macos")))]
mod huge_repository_scan_benchmarks {
    use super::{Config, ContextStreamClient, HashManifestData};
    use std::io;
    use std::time::{Duration, Instant};

    const FILE_COUNTS_ENV: &str = "CONTEXTSTREAM_HUGE_SCAN_FILE_COUNTS";
    const DEFAULT_FILE_COUNTS: &str = "10k";
    const MAX_FILE_COUNT: usize = 1_000_000;
    const FILES_PER_SHARD: usize = 1_000;

    fn invalid_file_count(message: impl Into<String>) -> io::Error {
        io::Error::new(io::ErrorKind::InvalidInput, message.into())
    }

    fn parse_file_count(raw: &str) -> io::Result<usize> {
        let normalized = raw.trim().to_ascii_lowercase().replace('_', "");
        let (digits, multiplier) = if let Some(digits) = normalized.strip_suffix('k') {
            (digits, 1_000usize)
        } else if let Some(digits) = normalized.strip_suffix('m') {
            (digits, 1_000_000usize)
        } else {
            (normalized.as_str(), 1usize)
        };
        let base = digits
            .parse::<usize>()
            .map_err(|error| invalid_file_count(format!("invalid file count {raw:?}: {error}")))?;
        let count = base
            .checked_mul(multiplier)
            .ok_or_else(|| invalid_file_count(format!("file count {raw:?} overflowed")))?;
        if count == 0 || count > MAX_FILE_COUNT {
            return Err(invalid_file_count(format!(
                "file count {count} must be between 1 and {MAX_FILE_COUNT}"
            )));
        }
        Ok(count)
    }

    fn requested_file_counts() -> io::Result<Vec<usize>> {
        let requested =
            std::env::var(FILE_COUNTS_ENV).unwrap_or_else(|_| DEFAULT_FILE_COUNTS.to_string());
        let mut counts = requested
            .split(',')
            .filter(|value| !value.trim().is_empty())
            .map(parse_file_count)
            .collect::<io::Result<Vec<_>>>()?;
        if counts.is_empty() {
            return Err(invalid_file_count(format!(
                "{FILE_COUNTS_ENV} must contain at least one file count"
            )));
        }
        counts.sort_unstable();
        counts.dedup();
        Ok(counts)
    }

    fn create_synthetic_repository(root: &std::path::Path, file_count: usize) -> io::Result<u64> {
        let mut content_bytes = 0u64;
        for shard_start in (0..file_count).step_by(FILES_PER_SHARD) {
            let shard = root
                .join("src")
                .join(format!("shard-{:06}", shard_start / FILES_PER_SHARD));
            std::fs::create_dir_all(&shard)?;
            let shard_end = (shard_start + FILES_PER_SHARD).min(file_count);
            for index in shard_start..shard_end {
                let content = format!("pub const SYNTHETIC_FILE_{index}: usize = {index};\n");
                content_bytes = content_bytes.saturating_add(content.len() as u64);
                std::fs::write(shard.join(format!("file-{index:07}.rs")), content)?;
            }
        }
        Ok(content_bytes)
    }

    fn manifest_from_cold_scan(cold: &super::LocalFileScan) -> HashManifestData {
        let hashes = cold
            .files
            .iter()
            .map(|file| {
                let path = file
                    .get("path")
                    .and_then(serde_json::Value::as_str)
                    .expect("synthetic scan result has a path");
                let content = file
                    .get("content")
                    .and_then(serde_json::Value::as_str)
                    .expect("synthetic scan result has text content");
                (path.to_string(), ContextStreamClient::sha256_hex(content))
            })
            .collect();
        HashManifestData {
            hashes,
            fingerprints: cold
                .fingerprints
                .iter()
                .filter(|(_, observed)| observed.reusable)
                .map(|(path, observed)| (path.clone(), observed.fingerprint.clone()))
                .collect(),
        }
    }

    #[cfg(target_os = "linux")]
    fn process_peak_rss_bytes() -> Option<u64> {
        std::fs::read_to_string("/proc/self/status")
            .ok()?
            .lines()
            .find_map(|line| line.strip_prefix("VmHWM:"))?
            .split_whitespace()
            .next()?
            .parse::<u64>()
            .ok()
            .and_then(|kibibytes| kibibytes.checked_mul(1024))
    }

    #[cfg(not(target_os = "linux"))]
    fn process_peak_rss_bytes() -> Option<u64> {
        None
    }

    fn milliseconds(duration: Duration) -> f64 {
        duration.as_secs_f64() * 1_000.0
    }

    #[test]
    fn huge_scan_file_count_presets_parse() {
        assert_eq!(parse_file_count("10k").expect("10k"), 10_000);
        assert_eq!(parse_file_count("100_000").expect("100k"), 100_000);
        assert_eq!(parse_file_count("1m").expect("1m"), 1_000_000);
        assert!(parse_file_count("0").is_err());
        assert!(parse_file_count("1000001").is_err());
    }

    #[test]
    #[ignore = "opt-in huge-repository cold/warm scanner benchmark"]
    fn huge_repository_cold_warm_scan_benchmark() -> Result<(), Box<dyn std::error::Error>> {
        for file_count in requested_file_counts()? {
            let fixture = tempfile::Builder::new()
                .prefix("contextstream-huge-scan-")
                .tempdir()?;
            let fixture_started = Instant::now();
            let expected_content_bytes = create_synthetic_repository(fixture.path(), file_count)?;
            let fixture_elapsed = fixture_started.elapsed();
            // Measure the steady-state warm path. Production never waits: a
            // repository this recent is read once and promoted by a later
            // scan. The benchmark ages its synthetic fixture outside both
            // measured scan intervals so every admitted fingerprint starts
            // behind the two-second racy-clean fence.
            std::thread::sleep(Duration::from_millis(2_100));
            let client = ContextStreamClient::new(Config::default());
            let root = fixture.path().to_string_lossy();
            let cursor_scope = format!("huge-scan-benchmark-{file_count}");

            // The cold timing deliberately includes constructing content
            // hashes, matching the work performed after the scanner returns
            // and producing the exact manifest consumed by the warm scan.
            let cold_started = Instant::now();
            let cold = client.read_local_files_scoped(
                root.as_ref(),
                usize::MAX,
                false,
                &cursor_scope,
                None,
                true,
            )?;
            let manifest = manifest_from_cold_scan(&cold);
            let cold_elapsed = cold_started.elapsed();
            let cold_peak_rss_bytes = process_peak_rss_bytes();

            let warm_started = Instant::now();
            let warm = client.read_local_files_scoped(
                root.as_ref(),
                usize::MAX,
                false,
                &cursor_scope,
                Some(&manifest),
                false,
            )?;
            let warm_elapsed = warm_started.elapsed();
            let warm_peak_rss_bytes = process_peak_rss_bytes();
            let warm_payload_content_bytes = warm
                .files
                .iter()
                .filter_map(|file| file.get("content").and_then(serde_json::Value::as_str))
                .map(str::len)
                .sum::<usize>();

            let report = serde_json::json!({
                "benchmark": "contextstream_huge_repository_cold_warm_scan",
                "file_count": file_count,
                "fixture_creation_wall_ms": milliseconds(fixture_elapsed),
                "cold": {
                    "wall_ms": milliseconds(cold_elapsed),
                    "files_hashed": cold.content_files_read,
                    "content_bytes_read": cold.content_bytes_read,
                    "metadata_reused_files": cold.reused_files,
                    "reusable_fingerprint_files": cold.fingerprints.values().filter(|entry| entry.reusable).count(),
                    "candidate_upload_files": cold.files.len(),
                    "scan_complete": cold.complete,
                    "process_peak_rss_bytes": cold_peak_rss_bytes,
                },
                "warm": {
                    "wall_ms": milliseconds(warm_elapsed),
                    "files_hashed": warm.content_files_read,
                    "content_bytes_read": warm.content_bytes_read,
                    "metadata_reused_files": warm.reused_files,
                    "reusable_fingerprint_files": warm.fingerprints.values().filter(|entry| entry.reusable).count(),
                    "candidate_upload_files": warm.files.len(),
                    "payload_content_bytes": warm_payload_content_bytes,
                    "scan_complete": warm.complete,
                    "process_peak_rss_bytes": warm_peak_rss_bytes,
                }
            });
            println!("{}", serde_json::to_string_pretty(&report)?);

            assert!(cold.complete, "cold scan must cover the whole fixture");
            assert_eq!(cold.files.len(), file_count);
            assert_eq!(cold.content_files_read, file_count);
            assert_eq!(cold.content_bytes_read, expected_content_bytes);
            assert_eq!(cold.reused_files, 0);
            assert_eq!(manifest.hashes.len(), file_count);
            assert_eq!(manifest.fingerprints.len(), file_count);

            assert!(warm.complete, "warm scan must cover the whole fixture");
            assert_eq!(warm.content_files_read, 0, "warm scan reopened content");
            assert_eq!(warm.content_bytes_read, 0, "warm scan reread content");
            assert_eq!(warm.reused_files, file_count);
            assert_eq!(warm.fingerprints.len(), file_count);
            assert_eq!(
                warm.fingerprints
                    .values()
                    .filter(|entry| entry.reusable)
                    .count(),
                file_count
            );
            assert!(
                warm.files.is_empty(),
                "unchanged warm files must not enter the upload payload"
            );
            assert_eq!(warm_payload_content_bytes, 0);

            fixture.close()?;
        }
        Ok(())
    }
}

#[cfg(test)]
mod caller_bound_response_cache_tests {
    use super::*;
    use std::collections::HashSet;

    fn key_text(key: &CacheKey) -> &str {
        match key {
            CacheKey::Custom(value) => value,
            other => panic!("caller-bound cache key was not opaque Custom: {other:?}"),
        }
    }

    fn all_family_keys(
        caller: &str,
        workspace_id: Uuid,
        project_id: Uuid,
        doc_id: Uuid,
    ) -> Vec<CacheKey> {
        let memory_body = serde_json::json!({
            "workspace_id": workspace_id,
            "project_id": project_id,
            "query": "private needle | with : delimiters",
            "node_type": "preference",
            "limit": 17,
        });
        let recall_body = serde_json::json!({
            "workspace_id": workspace_id,
            "project_id": project_id,
            "query": "private recall query",
            "limit": 9,
        });
        let search_body = serde_json::json!({
            "workspace_id": workspace_id,
            "query": "private source query",
            "search_type": "hybrid",
            "limit": 23,
        });

        vec![
            ContextStreamClient::credit_balance_cache_key(caller),
            ContextStreamClient::account_context_cache_key(caller),
            ContextStreamClient::workspace_cache_key(caller, workspace_id),
            ContextStreamClient::project_cache_key(caller, project_id),
            ContextStreamClient::project_overview_cache_key(caller, project_id),
            ContextStreamClient::project_agent_map_cache_key(caller, project_id),
            ContextStreamClient::project_index_status_cache_key(caller, project_id),
            ContextStreamClient::memory_search_cache_key(caller, &memory_body),
            ContextStreamClient::session_recall_cache_key(caller, &recall_body),
            ContextStreamClient::docs_list_cache_key(
                caller,
                Some(workspace_id),
                Some(project_id),
                Some("design:spec"),
                Some(true),
                Some("private docs query | exact"),
                Some(41),
            ),
            ContextStreamClient::doc_get_cache_key(caller, doc_id),
            ContextStreamClient::search_cache_key(caller, "/search/hybrid", &search_body),
            ContextStreamClient::integration_status_cache_key(
                caller,
                "notion:private",
                workspace_id,
            ),
        ]
    }

    #[tokio::test]
    async fn caller_identity_fails_closed_and_preserves_explicit_stdio() {
        assert_eq!(current_client_cache_identity(), None);
        assert_eq!(client_cache_identity_for_session_key(None), None);
        assert_eq!(
            client_cache_identity_for_session_key(Some(SessionKey::AnonymousHttp(
                "anonymous-partition".to_string(),
            ))),
            None
        );

        let anonymous = run_with_session_key(
            SessionKey::for_anonymous_http("anonymous-request"),
            || async { current_client_cache_identity() },
        )
        .await;
        assert_eq!(anonymous, None);

        let local_first = run_with_session_key(SessionKey::Local, || async {
            current_client_cache_identity()
        })
        .await
        .expect("explicit stdio marker is cacheable");
        let local_second = run_with_session_key(SessionKey::Local, || async {
            current_client_cache_identity()
        })
        .await
        .expect("explicit stdio marker remains cacheable");
        assert_eq!(local_first, local_second);
        assert!(local_first.starts_with("l:stdio:"));

        let jwt = run_with_session_key(
            SessionKey::for_http_jwt("raw-jwt-subject", Some("raw-session-id")),
            || async { current_client_cache_identity() },
        )
        .await
        .expect("authenticated JWT caller is cacheable");
        let api_key = run_with_session_key(
            SessionKey::for_http_api_key("raw-api-key", Some("raw-session-id")),
            || async { current_client_cache_identity() },
        )
        .await
        .expect("authenticated API-key caller is cacheable");
        assert_ne!(jwt, api_key);
        for identity in [&jwt, &api_key] {
            assert!(!identity.contains("raw-jwt-subject"));
            assert!(!identity.contains("raw-api-key"));
            assert!(!identity.contains("raw-session-id"));
        }
    }

    #[test]
    fn framed_keys_reject_delimiter_and_optional_field_collisions() {
        let caller = "caller|with:delimiters";
        let left = ContextStreamClient::caller_bound_cache_key(
            "test:",
            "contextstream-client-test-cache-v2",
            caller,
            &[("first", Some(b"a")), ("second", Some(b"bc"))],
        );
        let right = ContextStreamClient::caller_bound_cache_key(
            "test:",
            "contextstream-client-test-cache-v2",
            caller,
            &[("first", Some(b"ab")), ("second", Some(b"c"))],
        );
        let absent = ContextStreamClient::caller_bound_cache_key(
            "test:",
            "contextstream-client-test-cache-v2",
            caller,
            &[("first", None), ("second", Some(b""))],
        );
        let present_empty = ContextStreamClient::caller_bound_cache_key(
            "test:",
            "contextstream-client-test-cache-v2",
            caller,
            &[("first", Some(b"")), ("second", None)],
        );
        assert_ne!(left, right);
        assert_ne!(absent, present_empty);

        let workspace_id = Uuid::new_v4();
        let project_id = Uuid::new_v4();
        let docs_left = ContextStreamClient::docs_list_cache_key(
            caller,
            Some(workspace_id),
            Some(project_id),
            Some("a|b"),
            Some(true),
            Some("c:d"),
            Some(10),
        );
        let docs_right = ContextStreamClient::docs_list_cache_key(
            caller,
            Some(workspace_id),
            Some(project_id),
            Some("a"),
            Some(true),
            Some("b|c:d"),
            Some(10),
        );
        let docs_absent = ContextStreamClient::docs_list_cache_key(
            caller,
            Some(workspace_id),
            Some(project_id),
            None,
            None,
            None,
            None,
        );
        let docs_present_empty = ContextStreamClient::docs_list_cache_key(
            caller,
            Some(workspace_id),
            Some(project_id),
            Some(""),
            None,
            None,
            None,
        );
        assert_ne!(docs_left, docs_right);
        assert_ne!(docs_absent, docs_present_empty);
    }

    #[test]
    fn every_response_cache_family_is_caller_partitioned_opaque_and_symmetric() {
        let workspace_id = Uuid::new_v4();
        let project_id = Uuid::new_v4();
        let doc_id = Uuid::new_v4();
        let caller_a = "raw-caller-a:credential";
        let caller_b = "raw-caller-b:credential";
        let keys_a = all_family_keys(caller_a, workspace_id, project_id, doc_id);
        let keys_a_again = all_family_keys(caller_a, workspace_id, project_id, doc_id);
        let keys_b = all_family_keys(caller_b, workspace_id, project_id, doc_id);

        assert_eq!(keys_a, keys_a_again, "read/write key construction drifted");
        assert_eq!(keys_a.len(), keys_b.len());
        for (key_a, key_b) in keys_a.iter().zip(&keys_b) {
            assert_ne!(key_a, key_b, "cache family did not partition callers");
            let text = key_text(key_a);
            assert!(text.contains(":v2:"));
            assert_eq!(text.rsplit(':').next().map(str::len), Some(64));
            for raw in [
                caller_a,
                "private needle",
                "private recall query",
                "private docs query",
                "private source query",
                "notion:private",
            ] {
                assert!(!text.contains(raw), "cache key leaked raw value {raw:?}");
            }
        }

        let unique: HashSet<_> = keys_a.iter().cloned().collect();
        assert_eq!(unique.len(), keys_a.len(), "cache family domains collided");

        let client = ContextStreamClient::new(Config::default());
        for (index, key) in keys_a.into_iter().enumerate() {
            let value = serde_json::json!({ "family_index": index });
            client.cache_response(Some(key.clone()), value.clone(), Duration::from_secs(30));
            assert_eq!(client.cached_response(Some(&key)), Some(value));
        }
    }

    #[test]
    fn absent_cache_key_bypasses_both_reads_and_writes() {
        let client = ContextStreamClient::new(Config::default());
        let caller_key = ContextStreamClient::memory_search_cache_key(
            "known-caller",
            &serde_json::json!({ "query": "private" }),
        );
        client.cache_response(
            Some(caller_key.clone()),
            serde_json::json!({ "cached": true }),
            Duration::from_secs(30),
        );
        let before = client.cache.len();

        assert_eq!(client.cached_response(None), None);
        client.cache_response(
            None,
            serde_json::json!({ "must_not_be_stored": true }),
            Duration::from_secs(30),
        );

        assert_eq!(client.cache.len(), before);
        assert_eq!(
            client.cached_response(Some(&caller_key)),
            Some(serde_json::json!({ "cached": true }))
        );
    }

    #[tokio::test]
    async fn cached_project_index_status_reads_only_the_caller_partition() {
        let client = ContextStreamClient::new(Config::default());
        let project_id = Uuid::new_v4();
        let value = serde_json::json!({
            "project_id": project_id,
            "indexed_file_count": 42,
        });

        run_with_session_key(SessionKey::Local, || async {
            assert_eq!(client.cached_project_index_status(project_id), None);
            let caller = current_client_cache_identity().expect("local caller identity");
            let key = ContextStreamClient::project_index_status_cache_key(&caller, project_id);
            client.cache_response(Some(key), value.clone(), Duration::from_secs(30));
            assert_eq!(
                client.cached_project_index_status(project_id),
                Some(value.clone())
            );
            assert_eq!(
                client.cached_project_index_status_for_checkout(
                    project_id,
                    Some("relative/checkout"),
                ),
                None,
                "an unroutable checkout must not read the project-wide cache"
            );
        })
        .await;

        assert_eq!(client.cached_project_index_status(project_id), None);
    }

    #[test]
    fn project_index_status_cache_keys_partition_checkouts_without_raw_paths() {
        let caller = "csuc:v2:j:caller";
        let project_id = Uuid::new_v4();
        let first = CheckoutRoutingScope {
            installation_id: Uuid::new_v4(),
            checkout_locator: "checkout-locator-v1:first".to_string(),
        };
        let second = CheckoutRoutingScope {
            installation_id: first.installation_id,
            checkout_locator: "checkout-locator-v1:second".to_string(),
        };
        let first_key = ContextStreamClient::project_index_status_cache_key_for_checkout(
            caller,
            project_id,
            Some(&first),
        );
        let second_key = ContextStreamClient::project_index_status_cache_key_for_checkout(
            caller,
            project_id,
            Some(&second),
        );
        let project_key = ContextStreamClient::project_index_status_cache_key_for_checkout(
            caller, project_id, None,
        );

        assert_ne!(first_key, second_key);
        assert_ne!(first_key, project_key);
        assert!(!format!("{first_key:?}").contains("checkout-locator-v1:first"));
    }

    #[tokio::test]
    async fn missing_and_anonymous_callers_cannot_evict_cached_responses() {
        let client = ContextStreamClient::new(Config::default());
        let key = ContextStreamClient::memory_search_cache_key(
            "known-caller",
            &serde_json::json!({ "query": "private" }),
        );
        let value = serde_json::json!({ "cached": true });
        client.cache_response(Some(key.clone()), value.clone(), Duration::from_secs(30));

        client.invalidate_custom_cache_prefix(MEMORY_SEARCH_CACHE_PREFIX);
        assert_eq!(client.cached_response(Some(&key)), Some(value.clone()));

        run_with_session_key(
            SessionKey::for_anonymous_http("anonymous-request"),
            || async {
                client.invalidate_custom_cache_prefix(MEMORY_SEARCH_CACHE_PREFIX);
            },
        )
        .await;
        assert_eq!(client.cached_response(Some(&key)), Some(value));

        run_with_session_key(SessionKey::Local, || async {
            client.invalidate_custom_cache_prefix(MEMORY_SEARCH_CACHE_PREFIX);
        })
        .await;
        assert_eq!(client.cached_response(Some(&key)), None);
    }

    #[test]
    fn search_key_includes_endpoint_but_excludes_learning_side_effect() {
        let caller = "caller";
        let base = serde_json::json!({ "query": "needle", "search_type": "hybrid" });
        let opted_in = serde_json::json!({
            "query": "needle",
            "search_type": "hybrid",
            "code_rerank_learning_opt_in": true,
        });
        let hybrid = ContextStreamClient::search_cache_key(caller, "/search/hybrid", &base);
        let keyword = ContextStreamClient::search_cache_key(caller, "/search/keyword", &base);
        let opted_in_key =
            ContextStreamClient::search_cache_key(caller, "/search/hybrid", &opted_in);
        assert_ne!(hybrid, keyword);
        assert_eq!(hybrid, opted_in_key);
    }

    #[test]
    fn ingest_batch_body_carries_checkout_provenance_without_raw_remote_credentials() {
        let workspace_id = Uuid::new_v4();
        let checkout = CheckoutProvenance {
            checkout_id: "checkout-v1:11111111-1111-4111-8111-111111111111".to_string(),
            installation_id: Some("22222222-2222-4222-8222-222222222222".to_string()),
            machine_id: Some("machine-a".to_string()),
            repository_fingerprint: "git-common-dir-v1:33333333-3333-4333-8333-333333333333"
                .to_string(),
            repository_identity: Some(
                "git-remote-v1:github.com/contextstream/mcp-server".to_string(),
            ),
            git_ref_kind: "branch".to_string(),
            git_branch: Some("feature/worktrees".to_string()),
            git_commit_sha: Some("a".repeat(40)),
            git_commit_timestamp: Some("2026-07-29T08:00:00+00:00".to_string()),
            is_default_branch: Some(false),
            dirty: Some(true),
            captured_at: "2026-07-29T09:00:00+00:00".to_string(),
        };
        let file = serde_json::json!({
            "path": "src/lib.rs",
            "content": "pub fn indexed() {}",
            "language": "rust",
            "source_modified_at": "2026-07-29T08:59:00+00:00",
        });
        let body = ContextStreamClient::ingest_batch_body(
            workspace_id,
            &[&file],
            Some(&["removed.rs".to_string()]),
            Some(&checkout),
            true,
        )
        .expect("ingest body");

        assert_eq!(
            body["expected_scope"]["workspace_id"],
            workspace_id.to_string()
        );
        assert_eq!(body["checkout"]["checkout_id"], checkout.checkout_id);
        assert_eq!(
            body["checkout"]["repository_identity"],
            "git-remote-v1:github.com/contextstream/mcp-server"
        );
        assert_eq!(body["files"][0]["machine_id"], "machine-a");
        assert_eq!(body["files"][0]["checkout_id"], checkout.checkout_id);
        assert_eq!(body["files"][0]["git_branch"], "feature/worktrees");
        assert_eq!(body["files"][0]["checkout_dirty"], true);
        assert_eq!(
            body["files"][0]["source_modified_at"],
            "2026-07-29T08:59:00+00:00"
        );
        assert!(body.get("local_root").is_none());
        assert!(body.get("local_git_remote_identity").is_none());
        assert!(body.get("local_git_remote").is_none());
        assert!(!body.to_string().contains("/Users/alice/dev/mcp"));
        assert!(!body.to_string().contains("secret"));
    }

    #[test]
    fn legacy_checkout_id_is_stable_and_root_scoped_in_client_validation() {
        let fingerprint = "git-common-dir-v1:11111111-1111-4111-8111-111111111111";
        let first = Path::new("/repo/worktree-a");
        let second = Path::new("/repo/worktree-b");
        let first_id = ContextStreamClient::legacy_checkout_id(first, fingerprint);
        assert_eq!(
            first_id,
            ContextStreamClient::legacy_checkout_id(first, fingerprint)
        );
        assert_ne!(
            first_id,
            ContextStreamClient::legacy_checkout_id(second, fingerprint)
        );
        assert_eq!(
            ContextStreamClient::parse_checkout_id(&first_id),
            Some(first_id)
        );
    }
}
